        const alreadyHidden = d.getAttribute?.('data-ag-ws-native-sep-hidden') === 'true';
        const isNativeHit = alreadyHidden
          || (leftEdge != null && isEdgeNativeResizeHandleNode(d, leftEdge, 28))
          || (rightEdge != null && isEdgeNativeResizeHandleNode(d, rightEdge, 28))
          || (auxLeftEdge != null && isEdgeNativeResizeHandleNode(d, auxLeftEdge, 28));
        if (isNativeHit) {
          pushUnique(d);
          continue;
        }
