      if (typeof window?.__agContextMeterViews?.openProfileHome === 'function') {
        if (pTokens) pTokens.hidden = true;
        if (profileHomeEnabled) {
          openPersonalProfileHome({ trigger: 'showPanel' });
        }
        return;
      }
      hideContextTooltip();
      closeColorPicker();
      // 跨浮层切换立即收起旧面板，杜绝双面板堆叠、叠影与双可交互
      setPanelVisibleSmooth(pContext, false, { immediate: true });
