  function refreshRegionPresetSelectOptions() {
    const sel = el('select-custom-region-preset');
    if (!sel || !sel.options) return;
    const core = typeof __AGContextMeterCore !== 'undefined' ? __AGContextMeterCore : null;
    const presets = core?.SUBSCRIPTION_REGIONS_PRESET || [];
    const curLang = getPanelLanguage();
    const ps = ANTIGRAVITY_TOKEN_DATA?.planStatus || {};
    const activeSpecKey = typeof resolvePlanSpecKey === 'function'
      ? resolvePlanSpecKey(ps.planTierOverride && ps.planTierOverride !== 'auto' ? ps.planTierOverride : (ps.tierKey || 'pro'))
      : (ps.tierKey || 'pro');
    for (let i = 0; i < sel.options.length; i++) {
      const opt = sel.options[i];
      if (!opt || opt.value === '' || opt.value === 'custom') continue;
      const p = presets.find(item => item.id === opt.value);
      if (!p) continue;
      const parts = formatPresetRegionLineParts(p, curLang, activeSpecKey);
      opt.textContent = parts.full || '';
    }
  }

  function hasClass(node, cls) {
    if (!node) return false;
    if (node.classList?.contains) return node.classList.contains(cls);
    return String(node.className || '').split(/\s+/).includes(cls);
  }
  function addClass(node, cls) {
    if (!node) return;
    if (node.classList?.add) { node.classList.add(cls); return; }
    const cur = String(node.className || '').trim();
    if (!cur.split(/\s+/).includes(cls)) node.className = cur ? `${cur} ${cls}` : cls;
  }
  function removeClass(node, cls) {
    if (!node) return;
    if (node.classList?.remove) { node.classList.remove(cls); return; }
    const parts = String(node.className || '').split(/\s+/).filter(c => c !== cls);
    node.className = parts.join(' ');
  }

  // 纯同步 UI 控件回填防护守卫（仅在纯同步赋值代码块内开启，严禁跨越 await）
  let isHydratingUiControls = false;
  function runWithUiHydration(fn) {
    const prev = isHydratingUiControls;
    isHydratingUiControls = true;
    try {
      return fn();
    } finally {
      isHydratingUiControls = prev;
    }
  }

  // 兼容老调用声明
  let isRestoringSettings = false;

  // 异步时序保护：用户主动修改序列号与恢复请求版本号
  let userActionSeq = 0;
  let restoreRequestSeq = 0;

  /* @INSERT_DROPDOWN_MODULE */
  function renderPlanSummaryPriceBadge(targetSymbol, targetNum, targetCycle, targetCnyText, options = {}) {
    const priceValEl = el('plan-summary-price-val');
    const priceCnyEl = el('plan-summary-price-cny');
    const badgeEl = el('plan-summary-price-badge');
    if (!priceValEl) return;

    if (activeBadgeTimerId) {
      clearTimeout(activeBadgeTimerId);
      activeBadgeTimerId = null;
    }
    if (activeCnyTimerId) {
      clearTimeout(activeCnyTimerId);
      activeCnyTimerId = null;
    }
    if (activeBadgeRafId && typeof cancelAnimationFrame === 'function') {
      cancelAnimationFrame(activeBadgeRafId);
      activeBadgeRafId = null;
    }

    if (targetNum === null || targetNum === undefined) {
      const displayStr = targetSymbol || t('plan.summary.priceUnsetShort');
      if (typeof priceValEl.replaceChildren === 'function') {
        priceValEl.textContent = displayStr;
      } else {
        priceValEl.textContent = displayStr;
      }
      if (priceCnyEl) priceCnyEl.textContent = targetCnyText || '';
      if (badgeEl && badgeEl.classList) badgeEl.classList.remove('is-animating');
      lastBadgePriceState = null;
      return;
    }

    const formattedFinalNum = targetNum !== null && targetNum !== undefined
      ? (Number(targetNum) % 1 === 0 ? String(Number(targetNum)) : Number(targetNum).toFixed(2))
      : '';

    // 轻量模拟环境安全兼容
    if (typeof priceValEl.querySelector !== 'function') {
      priceValEl.textContent = `${targetSymbol}${formattedFinalNum}${targetCycle}`;
      if (priceCnyEl) priceCnyEl.textContent = targetCnyText;
      lastBadgePriceState = {
        symbol: targetSymbol,
        num: targetNum !== null ? Number(targetNum) : 0,
        cycle: targetCycle,
        cnyText: targetCnyText
      };
      return;
    }

    const hasRaf = typeof requestAnimationFrame === 'function';
    const forceDirect = options.forceDirect || !hasRaf || !lastBadgePriceState;

    if (forceDirect) {
      priceValEl.innerHTML = `<span class="badge-symbol-anim">${targetSymbol}</span><span class="badge-num-anim">${formattedFinalNum}</span><span class="badge-cycle-anim">${targetCycle}</span>`;
      if (priceCnyEl) priceCnyEl.textContent = targetCnyText;
      lastBadgePriceState = {
        symbol: targetSymbol,
        num: targetNum !== null ? Number(targetNum) : 0,
        cycle: targetCycle,
        cnyText: targetCnyText
      };
      return;
    }

    const startNum = (lastBadgePriceState && Number.isFinite(lastBadgePriceState.num))
      ? lastBadgePriceState.num
      : (Number(targetNum) || 0);
    const endNum = targetNum !== null ? Number(targetNum) : 0;
    const startSymbol = lastBadgePriceState?.symbol || targetSymbol;
    const endSymbol = targetSymbol;

    // 确保内部 DOM 结构完整
    let symbolEl = priceValEl.querySelector?.('.badge-symbol-anim');
    let numEl = priceValEl.querySelector?.('.badge-num-anim');
    let cycleEl = priceValEl.querySelector?.('.badge-cycle-anim');

    if (!symbolEl || !numEl || !cycleEl) {
      priceValEl.innerHTML = `<span class="badge-symbol-anim">${startSymbol}</span><span class="badge-num-anim">${formattedFinalNum}</span><span class="badge-cycle-anim">${targetCycle}</span>`;
      symbolEl = priceValEl.querySelector?.('.badge-symbol-anim');
      numEl = priceValEl.querySelector?.('.badge-num-anim');
      cycleEl = priceValEl.querySelector?.('.badge-cycle-anim');
    }

    if (cycleEl) cycleEl.textContent = targetCycle;

    // 1. 货币符号消散再切换动画 (Symbol Dissolve & Crossfade)
    if (startSymbol !== endSymbol && symbolEl && symbolEl.classList) {
      symbolEl.classList.remove('is-entering');
      symbolEl.classList.add('is-dissolving');

      activeBadgeTimerId = setTimeout(() => {
        symbolEl.textContent = endSymbol;
        symbolEl.classList.remove('is-dissolving');
        symbolEl.classList.add('is-entering');
        try { void symbolEl.offsetWidth; } catch { }
        setTimeout(() => {
          symbolEl.classList?.remove?.('is-entering');
        }, 180);
        activeBadgeTimerId = null;
      }, 160);
    } else if (symbolEl) {
      symbolEl.textContent = endSymbol;
    }

    // 2. CNY 折合平滑渐变
    if (priceCnyEl && priceCnyEl.textContent !== targetCnyText) {
      try {
        priceCnyEl.style.transition = 'opacity 0.18s ease';
        priceCnyEl.style.opacity = '0.2';
        activeCnyTimerId = setTimeout(() => {
          priceCnyEl.textContent = targetCnyText;
          priceCnyEl.style.opacity = '0.85';
          activeCnyTimerId = null;
        }, 140);
      } catch {
        priceCnyEl.textContent = targetCnyText;
      }
    }

    // 3. 数字滚动/递减递增动画 (Rolling Numeric Count Tween)
    if (startNum !== endNum && numEl) {
      if (badgeEl && badgeEl.classList) badgeEl.classList.add('is-animating');

      const startTime = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
      const duration = 500;
      const easeOut = t => 1 - Math.pow(1 - t, 4);

      const step = now => {
        const elapsed = Math.max(0, now - startTime);
        const progress = Math.min(1, elapsed / duration);
        const eased = easeOut(progress);
        const currentVal = startNum + (endNum - startNum) * eased;

        if (progress < 1) {
          if (endNum % 1 !== 0) {
            numEl.textContent = currentVal >= 100 ? String(Math.round(currentVal)) : currentVal.toFixed(2);
          } else {
            numEl.textContent = String(Math.round(currentVal));
          }
          activeBadgeRafId = requestAnimationFrame(step);
        } else {
          numEl.textContent = formattedFinalNum;
          if (badgeEl && badgeEl.classList) badgeEl.classList.remove('is-animating');
          activeBadgeRafId = null;
        }
      };

      activeBadgeRafId = requestAnimationFrame(step);
    } else if (numEl) {
      numEl.textContent = formattedFinalNum;
    }

    lastBadgePriceState = {
      symbol: targetSymbol,
      num: endNum,
      cycle: targetCycle,
      cnyText: targetCnyText
    };
  }

  function renderPlanDetail(ps) {
    if (!ps) return;
    const isCustomTier = Boolean(ps.sources?.tier === 'custom' || (ps.planTierOverride && ps.planTierOverride !== 'auto'));
    const sumTxt = el('plan-summary-text');
    const hasIdentifiedTier = Boolean(
      (ps.status === 'identified' || isCustomTier) &&
      ps.tierName &&
      ps.tierName !== '未知'
    );
    const tierDisplay = hasIdentifiedTier
      ? (typeof localizePlanTierName === 'function' ? localizePlanTierName(ps.tierName) : ps.tierName)
      : t('plan.tier.pending');
    if (sumTxt) {
      const modeTxt = isCustomTier
        ? t('plan.summary.custom')
        : (ps.status === 'identified' ? t('plan.summary.identified') : (ps.hasCustomSettings ? t('plan.summary.custom') : t('plan.summary.unknown')));
      sumTxt.textContent = `${tierDisplay} · ${modeTxt} · ${t('plan.summary.justNow')}`;
    }

    // 实时联动顶部订阅费与汇率胶囊（零括号；unsplit Ultra 明确显示区间或待选择档位）
    const curSymbol = ps.currencySymbol || '$';
    let targetSymbol = '$';
    let targetNum = null;
    let targetCycle = t('plan.summary.perMonth');
    let targetCny = '';

    if (ps.actualPricePaid === 0 || ps.isZeroExtraCost) {
      targetSymbol = curSymbol;
      targetNum = 0;
      targetCycle = t('plan.summary.perMonth');
      targetCny = t('plan.summary.freeWithPlan');
    } else if (ps.actualPricePaid !== null && ps.actualPricePaid !== undefined) {
      targetSymbol = curSymbol;
      targetNum = Number(ps.actualPricePaid);
      targetCycle = t('plan.summary.perMonth');
      const sec = formatSubscriptionSecondaryConversion(ps.actualPricePaid, ps.currency || 'USD', ps.region, { short: true });
      targetCny = sec ? `· ${sec}` : '';
    } else if (ps.officialPriceMonthly !== null && ps.officialPriceMonthly !== undefined) {
      targetSymbol = '$';
      targetNum = Number(ps.officialPriceMonthly);
      targetCycle = t('plan.summary.perMonth');
      const sec = formatSubscriptionSecondaryConversion(targetNum, 'USD', ps.region, { short: true });
      targetCny = sec ? `· ${sec}` : '';
    } else if (ps.tierKey === 'ultra') {
      targetSymbol = t('plan.ultraRangePrice');
      targetNum = null;
      targetCycle = '';
      targetCny = t('plan.summary.priceUnsetShort');
    } else {
      targetSymbol = t('plan.summary.priceUnsetShort');
      targetNum = null;
      targetCycle = '';
      targetCny = t('plan.summary.priceUnsetCny');
    }

    renderPlanSummaryPriceBadge(targetSymbol, targetNum, targetCycle, targetCny);

    const detName = el('p-det-name');
    if (detName) detName.textContent = tierDisplay;
    const detAcc = el('p-det-account');
    if (detAcc) detAcc.textContent = ps.email || t('plan.account.unknown');

    // 守卫：若当前不在 Token 统计视图或详情处于收起状态，严禁异步返回时撑开详情面板
    const cardEl = el('plan-detail-card');
    if (cardEl && (activeTokenView !== 'tokens' || !planDetailExpanded)) {
      cardEl.style.display = 'none';
      cardEl.classList?.remove?.('is-expanded');
    }

    const detCountry = el('p-det-country');
    const tagCountry = el('p-det-country-tag');
    const tagTier = el('p-det-tier-tag');
    if (tagTier) {
      tagTier.style.display = 'inline-block';
      tagTier.textContent = isCustomTier ? t('plan.source.customPlan') : t('plan.source.autoDetected');
    }
    const directTierSel = el('direct-tier-select');
    const directCountrySel = el('direct-country-select');
    const rawCountryStr = ps.country ? String(ps.country).trim() : '';
    const isCountryUnknown = !rawCountryStr || rawCountryStr === '未知' || rawCountryStr === 'Unknown' || rawCountryStr.includes('未设置');
    const countryText = isCountryUnknown ? '未知' : rawCountryStr;
    const countryDisplay = countryText === '未知' ? t('plan.country.unknown') : (localizeRegionDisplayValue(countryText) || countryText);
    if (detCountry) detCountry.textContent = countryDisplay;
    if (tagCountry) {
      tagCountry.style.display = ps.countrySource === 'custom' ? 'inline-block' : 'none';
      tagCountry.textContent = ps.countrySource === 'custom' ? t('plan.tag.custom') : '';
    }

    const detReg = el('p-det-region');
    const tagReg = el('p-det-region-tag');
    let regText = ps.subscriptionRegion || ps.region || '未知';
    if (regText.includes('未在当前会话中获取') || regText.trim() === '未知' || regText.trim() === 'Unknown') regText = '未知';
    const regDisplay = regText === '未知' ? t('plan.region.unknown') : (localizeRegionDisplayValue(regText) || regText);
    if (detReg) detReg.textContent = regDisplay;
    if (tagReg) {
      tagReg.style.display = ps.regionSource === 'custom' ? 'inline-block' : 'none';
      tagReg.textContent = ps.regionSource === 'custom' ? t('plan.tag.custom') : '';
    }

    const detCur = el('p-det-currency');
    const tagCur = el('p-det-currency-tag');
    const directCurSel = el('direct-currency-select');
    const curText = ps.currency || 'USD';
    if (detCur) detCur.textContent = curText;
    if (tagCur) {
      tagCur.style.display = ps.currencySource === 'custom' ? 'inline-block' : 'none';
      tagCur.textContent = ps.currencySource === 'custom' ? t('plan.tag.custom') : '';
    }

    // 同步详情面板内的下拉控件值
    runWithUiHydration(() => {
      if (directTierSel) {
        directTierSel.value = ps.planTierOverride || 'auto';
      }
      if (directCountrySel) {
        if (countryText !== '未知' && directCountrySel.options) {
          const normC = localizeRegionDisplayValue(countryText) || countryText;
          const exists = Array.from(directCountrySel.options).some(o => o.value === countryText || o.value === normC);
          if (!exists && typeof document.createElement === 'function') {
            const opt = document.createElement('option');
            opt.value = countryText;
            opt.textContent = '🌐 ' + normC;
            directCountrySel.appendChild?.(opt);
          }
        }
        directCountrySel.value = countryText;
      }
      if (directCurSel) {
        directCurSel.value = curText === 'NTD' ? 'TWD' : curText;
      }
    });

    if (typeof refreshDirectPlanTierDisplay === 'function') {
      refreshDirectPlanTierDisplay(ps.planTierOverride || 'auto');
    }
    if (typeof refreshDirectCountryDisplay === 'function') {
      refreshDirectCountryDisplay(countryText);
    }
    if (typeof refreshDirectRegionDisplay === 'function') {
      refreshDirectRegionDisplay(regText);
    }
    if (typeof refreshDirectCurrencyDisplay === 'function') {
      refreshDirectCurrencyDisplay(curText);
    }

    const tierPill = el('quota-plan-tier-pill');
    if (tierPill) {
      if (hasIdentifiedTier) {
        setQuotaHiddenIfChanged(tierPill, false);
        setQuotaTextIfChanged(tierPill, tierDisplay);
      } else if (!quotaState.snapshot?.planTierName || quotaState.snapshot.planTierName === '未知') {
        setQuotaHiddenIfChanged(tierPill, false);
        setQuotaTextIfChanged(tierPill, t('plan.tier.pending'));
      }
    }

    if (typeof renderAccountsOverviewSection === 'function' && accountsUiState?.overview) {
      try { renderAccountsOverviewSection(); } catch { }
    }

    const detAcq = el('p-det-acq');
    const tagAcq = el('p-det-acq-tag');
    if (detAcq) detAcq.textContent = localizeAcquisitionSource(ps.acquisitionSource || ps.acquisitionSourceName);
    if (tagAcq) {
      const isPromo = ps.acquisitionSource && ps.acquisitionSource !== 'normal_paid';
      tagAcq.style.display = isPromo ? 'inline-block' : 'none';
      tagAcq.textContent = isPromo ? t('plan.tag.promo') : '';
    }

    const detPrice = el('p-det-price');
    const tagPrice = el('p-det-price-tag');
    const isPresetMode = ps.priceMode === 'preset';
    const btnModePreset = el('btn-mode-preset');
    const btnModeCustom = el('btn-mode-custom');
    if (btnModePreset) setPillActive(btnModePreset, isPresetMode);
    if (btnModeCustom) setPillActive(btnModeCustom, !isPresetMode);

    if (detPrice) {
      const cycleText = localizeBillingCycleLabel(ps.billingCycle);
      const acqLabel = localizeAcquisitionSource(ps.acquisitionSource || ps.acquisitionSourceName);
      if (ps.actualPricePaid === 0 || ps.isZeroExtraCost) {
        detPrice.textContent = `${curSymbol}0 · ${cycleText}`;
      } else if (ps.actualPricePaid !== null && ps.actualPricePaid !== undefined) {
        const secPart = formatSubscriptionSecondaryConversion(ps.actualPricePaid, ps.currency || 'USD', ps.region, { detail: true });
        const paidFormatted = Number(ps.actualPricePaid) % 1 === 0 ? Number(ps.actualPricePaid) : Number(ps.actualPricePaid).toFixed(2);
        detPrice.textContent = secPart ? `${curSymbol}${paidFormatted} · ${cycleText} · ${secPart}` : `${curSymbol}${paidFormatted} · ${cycleText}`;
      } else if (ps.officialPriceMonthly !== null && ps.officialPriceMonthly !== undefined) {
        const secPart = formatSubscriptionSecondaryConversion(ps.officialPriceMonthly, 'USD', ps.region, { detail: true });
        detPrice.textContent = secPart ? `$${ps.officialPriceMonthly}${t('plan.summary.perMonth')} · ${secPart}` : `$${ps.officialPriceMonthly}${t('plan.summary.perMonth')}`;
      } else if (ps.tierKey === 'ultra') {
        detPrice.textContent = `${t('plan.ultraRangePrice')} · ${t('plan.priceUnsetNote')}`;
      } else {
        detPrice.textContent = `${acqLabel} · ${t('plan.priceUnsetNote')}`;
      }
    }
    if (tagPrice) {
      tagPrice.style.display = 'inline-block';
      if (ps.actualPricePaid === 0 || ps.isZeroExtraCost) {
        tagPrice.textContent = t('plan.tag.manualFree');
      } else if (ps.priceMode === 'custom' || ps.priceSource === 'custom') {
        tagPrice.textContent = t('plan.tag.userPaid');
      } else if (ps.priceSource === 'preset_region' && ps.actualPricePaid !== null && ps.actualPricePaid !== undefined) {
        tagPrice.textContent = t('plan.tag.regionRef');
      } else if (ps.officialPriceMonthly !== null && ps.officialPriceMonthly !== undefined) {
        tagPrice.textContent = t('plan.tag.publicRef');
      } else {
        tagPrice.textContent = t('plan.tag.unset');
      }
    }

    // 套餐权益规格 strip（倍率 / 云存储 / 官方 Flow 月积分 / Cloud Credits）
    const specsEl = el('p-det-tier-specs');
    const resolvedSpecKey = typeof resolvePlanSpecKey === 'function'
      ? resolvePlanSpecKey(ps.tierKey, ps.multiplier, (ps.planTierOverride && ps.planTierOverride !== 'auto') ? ps.planTierOverride : ps.tierName)
      : (ps.tierKey || 'pro');
    const specObj = ps.planSpec || (typeof getPlanTierSpec === 'function' ? getPlanTierSpec(resolvedSpecKey) : null);
    const specLangSuffix = currentPanelLanguage === 'en' ? 'En' : (currentPanelLanguage === 'zh-TW' ? 'Tw' : 'Zh');
    if (specsEl) {
      if (specObj) {
        const items = [];
        const winText = specObj[`windowDesc${specLangSuffix}`] || specObj.windowDescZh;
        if (winText) items.push(winText);
        if (specObj.storage) items.push(t('plan.specs.storage', { val: specObj.storage }));
        const flowText = specObj[`flowOfficial${specLangSuffix}`] || specObj.flowOfficialZh;
        if (flowText) items.push(flowText);
        const ccText = specObj[`cloudCredits${specLangSuffix}`] || specObj.cloudCreditsZh;
        if (ccText) items.push(ccText);
        specsEl.textContent = items.join(' · ') || '—';
      } else {
        specsEl.textContent = '—';
      }
    }

    const dtVal = el('p-dt-validity');
    const ddVal = el('p-det-validity');
    if (dtVal && ddVal) {
      if (ps.validEndDate) {
        dtVal.style.display = 'block';
        ddVal.style.display = 'block';
        ddVal.textContent = ps.isExpired
          ? t('plan.validity.expired', { date: ps.validEndDate })
          : t('plan.validity.active', { date: ps.validEndDate });
        ddVal.style.color = ps.isExpired ? '#ef4444' : 'var(--ag-text-secondary)';
      } else {
        dtVal.style.display = 'none';
        ddVal.style.display = 'none';
      }
    }

    const dtNote = el('p-dt-note');
    const ddNote = el('p-det-note');
    if (dtNote && ddNote) {
      if (ps.customNote) {
        dtNote.style.display = 'block';
        ddNote.style.display = 'block';
        ddNote.textContent = String(ps.customNote);
      } else {
        dtNote.style.display = 'none';
        ddNote.style.display = 'none';
      }
    }

    // Prompt / Flow 额度池：区分宿主实报 vs 套餐估算，并在切换后附带次要实报对照行
    const pPrompt = el('p-det-prompt-credits');
    const pFlow = el('p-det-flow-credits');
    const isEstBasis = ps.creditDisplayBasis === 'plan_estimate';
    const effPrompt = ps.effectivePromptCredits || ps.promptCredits;
    const effFlow = ps.effectiveFlowCredits || ps.flowCredits;

    const renderCreditCell = (cellEl, effObj, liveObj, extraRightTxt = '') => {
      if (!cellEl) return;
      if (typeof cellEl.replaceChildren === 'function') {
        cellEl.replaceChildren();
        const topRow = document.createElement('div');
        topRow.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap;';
        const mainSpan = document.createElement('span');
        const mainStr = effObj
          ? t('plan.credits.avail', { avail: effObj.available ?? '—', monthly: effObj.monthly ?? '—' })
          : '—';
        mainSpan.textContent = extraRightTxt ? `${mainStr} · ${extraRightTxt}` : mainStr;
        const srcPill = document.createElement('span');
        srcPill.className = `plan-source-pill${isEstBasis ? '' : ' is-host'}`;
        srcPill.textContent = isEstBasis ? t('plan.source.planEstimate') : t('plan.source.hostLive');
        topRow.appendChild(mainSpan);
        topRow.appendChild(srcPill);
        cellEl.appendChild(topRow);
        if (isEstBasis && liveObj && (liveObj.available != null || liveObj.monthly != null)) {
          const subSpan = document.createElement('span');
          subSpan.className = 'plan-credit-host-sub';
          subSpan.textContent = `${t('plan.credits.hostActualPrefix')}${t('plan.credits.avail', { avail: liveObj.available ?? '—', monthly: liveObj.monthly ?? '—' })}`;
          cellEl.appendChild(subSpan);
        }
      } else {
        const mainStr = effObj
          ? t('plan.credits.avail', { avail: effObj.available ?? '—', monthly: effObj.monthly ?? '—' })
          : '—';
        cellEl.textContent = `${mainStr} · ${isEstBasis ? t('plan.source.planEstimate') : t('plan.source.hostLive')}`;
      }
    };

    if (pPrompt && effPrompt) {
      renderCreditCell(pPrompt, effPrompt, ps.promptCredits);
      const pLegacy = el('p-det-credits');
      if (pLegacy && pLegacy !== pPrompt && pLegacy.parentElement !== pPrompt) {
        pLegacy.textContent = t('plan.credits.avail', { avail: effPrompt.available ?? '—', monthly: effPrompt.monthly ?? '—' });
      }
    }
    if (pFlow && effFlow) {
      const officialFlowExtra = specObj?.[`flowOfficial${specLangSuffix}`]
        || effFlow.officialText
        || specObj?.flowOfficialZh
        || '';
      renderCreditCell(pFlow, effFlow, ps.flowCredits, officialFlowExtra);
    }

    const detTime = el('p-det-time');
    if (detTime) {
      const dateLocale = currentPanelLanguage === 'en' ? 'en-US' : (currentPanelLanguage === 'zh-TW' ? 'zh-TW' : 'zh-CN');
      const timeStr = ps.updatedAt ? new Date(ps.updatedAt).toLocaleString(dateLocale) : '—';
      const snapStr = t('plan.price.tableSnapshot', { date: ps.pricingTableVerifiedDate || '2026-11' });
      detTime.textContent = `${timeStr} · ${snapStr}`;
    }
  }

  function setPillActive(node, active) {
    if (!node) return;
    node.classList?.toggle?.('active', active);
    const cur = node.getAttribute('class') || 'switch-pill-btn';
    if (active) {
      if (!cur.includes('active')) node.setAttribute('class', (cur + ' active').trim());
    } else {
      node.setAttribute('class', cur.replace(/\bactive\b/g, '').trim());
    }
  }

  function formatCompactTokenCount(v) {
    const n = Number(v) || 0;
    if (n >= 1e9) return `${(n / 1e9).toFixed(2)}B`;
    if (n >= 1e6) return `${(n / 1e6).toFixed(1)}M`;
    if (n >= 1e3) return `${(n / 1e3).toFixed(1)}K`;
    return String(n);
  }

  // 数据源切换（全部 / 桌面 / CLI）与分账号账本筛选
  let activeTokenSource = 'all';
  let activeTokenAccountFilter = 'all'; // 'all' | 'unattributed' | 'acct_xxx'
  const accountsUiState = {
    overview: null,
    loadError: null,
    toolsPreview: null,
    feedback: '',
    feedbackTone: 'info',
    busy: false,
    mutationSeq: 0,
    autoSwitchDraft: {
      dirty: false,
      saving: false,
      saveStatusKey: '',
      saveErrorDetail: '',
      values: null
    },
    removeModal: {
      open: false,
      email: '',
      scopeKey: '',
      isActive: false,
      busy: false,
      error: ''
    }
  };
  function resetAccountScopedViewOffsets() {
    heatPageOffset = 0;
    heatMonthOffset = 0;
    heatYearOffset = 0;
    modelUsageOffsetDays = 0;
    modelUsageLockedKey = null;
    modelUsageHoveredKey = null;
    if (typeof resetCumSelectionState === 'function') resetCumSelectionState();
  }
  function switchTokenSource(src) {
    activeTokenSource = src;
    try { localStorage?.setItem('ag_token_source_v1', src); } catch { }
    if (typeof resetCumSelectionState === 'function') resetCumSelectionState();
    setPillActive(el('src-tab-all'), src === 'all');
    setPillActive(el('src-tab-desktop'), src === 'desktop');
    setPillActive(el('src-tab-cli'), src === 'cli');

    if (ANTIGRAVITY_TOKEN_DATA.rawPayload) {
      applyTokenHistoryPayload(ANTIGRAVITY_TOKEN_DATA.rawPayload, { renderTokenSubview: true });
    } else {
      const bySrc = ANTIGRAVITY_TOKEN_DATA.dailyMapBySource || {};
      const srcMap = bySrc[src] || bySrc.all || ANTIGRAVITY_TOKEN_DATA.dailyMap;
      ANTIGRAVITY_TOKEN_DATA.dailyMap = srcMap;
      const mBySrc = ANTIGRAVITY_TOKEN_DATA.dailyModelMapBySource || {};
      ANTIGRAVITY_TOKEN_DATA.dailyModelMap = mBySrc[src] || mBySrc.all || ANTIGRAVITY_TOKEN_DATA.dailyModelMap || {};
      renderActiveHeatView(true);
      renderActiveCostEstimateView();
      renderModelUsageView();
    }
    if (activeTokenView === 'requests') {
      renderRequestsLiveView({ force: true });
    }
  }
  el('src-tab-all')?.addEventListener('click', () => switchTokenSource('all'));
  el('src-tab-desktop')?.addEventListener('click', () => switchTokenSource('desktop'));
  el('src-tab-cli')?.addEventListener('click', () => switchTokenSource('cli'));

  // 视图切换（Token 统计 / API 等值估算）
  activeTokenView = 'tokens';

  // 费用面板紧凑摘要与展开详情切换
  let costDetailsExpanded = false;
  function toggleCostDetails(expand) {
    if (expand === undefined) costDetailsExpanded = !costDetailsExpanded;
    else costDetailsExpanded = Boolean(expand);

    const pane = el('cost-details-pane');
    const btn = el('btn-cost-details-toggle');
    const pTokens = el('panel-tokens');

    if (pane) {
      pane.style.display = costDetailsExpanded ? 'block' : 'none';
      if (costDetailsExpanded) pane.style.animation = 'agFadeIn .2s cubic-bezier(0.16,1,0.3,1)';
    }
    if (btn) btn.textContent = costDetailsExpanded ? t('cost.btnCollapse') : t('cost.btnExpand');
    if (pTokens) {
      const isCompact = activeTokenView === 'cost' && !costDetailsExpanded;
      pTokens.classList?.toggle?.('cost-compact-view', isCompact);
      const curCls = pTokens.getAttribute?.('class') || '';
      if (isCompact) {
        if (!curCls.includes('cost-compact-view')) pTokens.setAttribute?.('class', (curCls + ' cost-compact-view').trim());
      } else {
        pTokens.setAttribute?.('class', curCls.replace(/\bcost-compact-view\b/g, '').trim());
      }
    }
    positionFloatingPanels();
  }
  el('cost-details-pane');
  el('cost-non-paid-badge');
  el('cost-scope-desc');
  el('tokens-main-view');
  el('btn-cost-details-toggle')?.addEventListener('click', () => toggleCostDetails());
  el('btn-cost-details-collapse')?.addEventListener('click', () => toggleCostDetails(false));
  el('btn-cost-fill-sub')?.addEventListener('click', () => {
    switchTokenView('tokens');
    setPlanDetailExpanded(true);
    togglePlanCustomForm(true);
  });
  toggleCostDetails(false);

  // 按模型 Token 统计状态与视图渲染
  let modelUsagePeriodDays = defaultViewPrefs.modelUsagePeriodDays;
  let modelUsageOffsetDays = 0;
  let modelUsageGroupBy = 'model';
  let modelUsageMetric = 'total';
  let modelUsageHideUnattr = false;
  let modelUsageScaleMode = 'mixed'; // 'mixed' | 'linear'
  let modelUsageLockedKey = null;
  let modelUsageHoveredKey = null;
  const OTHER_SERIES_KEY = '__other_series__';

  function formatModelDateShort(dateStr) {
    const parts = String(dateStr || '').split('-').map(Number);
    if (parts.length !== 3 || parts.some(n => !Number.isFinite(n))) return dateStr || '';
    const [y, m, d] = parts;
    if (currentPanelLanguage === 'en') {
      const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
      return `${months[m - 1] || m} ${d}`;
    }
    return `${m}/${String(d).padStart(2, '0')}`;
  }

  function formatModelRangeLabel(startStr, endStr) {
    const sp = String(startStr || '').split('-').map(Number);
    const ep = String(endStr || '').split('-').map(Number);
    if (sp.length !== 3 || ep.length !== 3) return `${startStr} – ${endStr}`;
    if (currentPanelLanguage === 'en') {
      const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
      if (sp[0] === ep[0] && sp[1] === ep[1]) {
        return `${months[sp[1] - 1]} ${sp[2]} – ${ep[2]}, ${ep[0]}`;
      }
      if (sp[0] === ep[0]) {
        return `${months[sp[1] - 1]} ${sp[2]} – ${months[ep[1] - 1]} ${ep[2]}, ${ep[0]}`;
      }
      return `${months[sp[1] - 1]} ${sp[2]}, ${sp[0]} – ${months[ep[1] - 1]} ${ep[2]}, ${ep[0]}`;
    }
    return sp[0] === ep[0]
      ? `${startStr} – ${String(ep[1]).padStart(2, '0')}-${String(ep[2]).padStart(2, '0')}`
      : `${startStr} – ${endStr}`;
  }

  function setClassFlag(node, cls, active) {
    if (!node || !node.classList) return;
    if (active) node.classList.add(cls);
    else node.classList.remove(cls);
  }

  function applyModelSeriesFocusHighlight() {
    const focusKey = modelUsageHoveredKey || modelUsageLockedKey || null;
    const barsEl = el('model-usage-bars');
    const legendEl = el('model-usage-legend');
    if (barsEl && barsEl.children) {
      for (const col of Array.from(barsEl.children)) {
        for (const child of Array.from(col.children || [])) {
          if (String(child.className || '').includes('model-usage-stack')) {
            for (const seg of Array.from(child.children || [])) {
              const k = seg.getAttribute?.('data-series-key');
              setClassFlag(seg, 'is-dimmed', Boolean(focusKey && k !== focusKey));
            }
          }
        }
      }
    }
    if (legendEl && legendEl.children) {
      for (const card of Array.from(legendEl.children)) {
        const k = card.getAttribute?.('data-series-key');
        setClassFlag(card, 'is-dimmed', Boolean(focusKey && k !== focusKey));
        setClassFlag(card, 'is-locked', Boolean(modelUsageLockedKey && k === modelUsageLockedKey));
      }
    }
  }

  function renderModelUsageView() {
    const viewEl = el('model-usage-view');
    if (!viewEl) return;

    setPillActive(el('model-period-7d'), modelUsagePeriodDays === 7);
    setPillActive(el('model-period-30d'), modelUsagePeriodDays === 30);
    setPillActive(el('model-group-model'), modelUsageGroupBy === 'model');
    setPillActive(el('model-group-variant'), modelUsageGroupBy === 'variant');
    setPillActive(el('model-metric-total'), modelUsageMetric === 'total');
    setPillActive(el('model-metric-nocache'), modelUsageMetric === 'noCache');
    setPillActive(el('model-scale-mixed'), modelUsageScaleMode === 'mixed');
    setPillActive(el('model-scale-linear'), modelUsageScaleMode === 'linear');

    const core = typeof __AGContextMeterCore !== 'undefined' ? __AGContextMeterCore : null;
    if (!core || typeof core.summarizeModelUsageWindow !== 'function') return;

    const todayStr = formatLocalYmd(new Date());
    const todayDate = new Date(todayStr + 'T00:00:00');
    const endDt = new Date(todayDate.getTime() - modelUsageOffsetDays * 86400000);
    const endDate = formatLocalYmd(endDt);

    const bySrcModel = ANTIGRAVITY_TOKEN_DATA.dailyModelMapBySource || {};
    const dailyModelMap = bySrcModel[activeTokenSource] || bySrcModel.all || ANTIGRAVITY_TOKEN_DATA.dailyModelMap || {};

    const isLightTone = host.getAttribute?.('data-theme') === 'light' || host.getAttribute?.('data-panel-tone') === 'light';
    const themeAccent = customColors?.tokenAccent || (typeof heatPreset !== 'undefined' && heatPreset !== 'purple' && typeof getEffectiveHeatmapScale === 'function'
      ? getEffectiveHeatmapScale()[3]
      : '');
    const summary = core.summarizeModelUsageWindow(dailyModelMap, {
      periodDays: modelUsagePeriodDays,
      endDate,
      groupBy: modelUsageGroupBy,
      metric: modelUsageMetric,
      hideUnattributed: modelUsageHideUnattr,
      theme: isLightTone ? 'light' : 'dark',
      accentColor: themeAccent || undefined,
      modelMetaByKey: ANTIGRAVITY_TOKEN_DATA.modelMetaByKey,
      unattributedLabel: t('modelsUsage.unattributed')
    });

    // 长尾折叠：图例大于 6 项时保留 Top 5 独立颜色 + 第 6 项「其他模型/档位」
    let effectiveLegend = Array.isArray(summary.legend) ? summary.legend.slice() : [];
    const foldedKeys = new Set();
    if (effectiveLegend.length > 6) {
      const top5 = effectiveLegend.slice(0, 5);
      const tail = effectiveLegend.slice(5);
      let otherTokens = 0;
      let otherSteps = 0;
      tail.forEach(item => {
        foldedKeys.add(item.key);
        otherTokens += Number(item.tokens) || 0;
        otherSteps += Number(item.steps) || 0;
      });
      const winTot = Math.max(1, Number(summary.windowTotalTokens) || 0);
      const otherPct = (otherTokens / winTot) * 100;
      top5.push({
        key: '__other_series__',
        label: t('modelsUsage.otherSeries'),
        color: '#71717a',
        tokens: otherTokens,
        steps: otherSteps,
        pct: otherPct,
        pctLabel: otherPct < 0.1 && otherTokens > 0 ? '<0.1%' : `${otherPct.toFixed(1)}%`
      });
      effectiveLegend = top5;
    }

    if (modelUsageLockedKey && !effectiveLegend.some(it => it.key === modelUsageLockedKey)) {
      modelUsageLockedKey = null;
    }

    const rangeLbl = el('model-usage-range-label');
    if (rangeLbl) rangeLbl.textContent = formatModelRangeLabel(summary.startDate, summary.endDate);
    const winTotEl = el('model-usage-window-total');
    if (winTotEl) winTotEl.textContent = `${formatCompactTokenCount(summary.windowTotalTokens)} Tokens`;

    const unattrBtn = el('model-toggle-unattr');
    if (unattrBtn) {
      const showBtn = summary.hasUnattributed || modelUsageHideUnattr;
      unattrBtn.style.display = showBtn ? 'inline-flex' : 'none';
      setPillActive(unattrBtn, modelUsageHideUnattr);
      unattrBtn.textContent = modelUsageHideUnattr ? t('modelsUsage.showUnattr') : t('modelsUsage.hideUnattr');
    }

    const firstUse = ANTIGRAVITY_TOKEN_DATA.firstUseDate || ANTIGRAVITY_TOKEN_DATA.summary?.firstUseDate || null;
    const allModelDates = Object.keys(dailyModelMap || {}).filter(k => /^\d{4}-\d{2}-\d{2}$/.test(k)).sort();
    const earliestKnown = allModelDates[0] && (!firstUse || allModelDates[0] < firstUse) ? allModelDates[0] : firstUse;
    const prevBtn = el('btn-model-win-prev');
    const nextBtn = el('btn-model-win-next');
    if (prevBtn) prevBtn.disabled = Boolean(earliestKnown && summary.startDate <= earliestKnown);
    if (nextBtn) nextBtn.disabled = modelUsageOffsetDays <= 0;

    const chartPxHeight = 140;
    const env = typeof core.resolveScaleEnvelope === 'function'
      ? core.resolveScaleEnvelope(summary.maxDayTotal, 'dailyBar')
      : { tier: '500M', anchor: 500e6, hCap: 1.0, refTicks: [1e6, 10e6, 100e6, 500e6], overflowThreshold: 500e6 };

    const gridWrap = el('model-usage-gridlines');
    const maxLblEl = el('model-chart-max-lbl');
    if (gridWrap) {
      const childrenArr = Array.from(gridWrap.children || []);
      const baseLines = [];
      childrenArr.forEach(node => {
        const cls = String(node.className || '');
        if (cls.includes('model-usage-tick-line')) {
          node.remove?.();
        } else {
          baseLines.push(node);
        }
      });
      if (modelUsageScaleMode === 'mixed' && typeof core.mapBarHeightPx === 'function') {
        gridWrap.style.display = 'block';
        baseLines.forEach(gl => { gl.style.display = 'none'; });
        const ticks = Array.isArray(env.refTicks) ? env.refTicks : [];
        const lastTick = ticks.length ? ticks[ticks.length - 1] : 0;
        ticks.forEach(tVal => {
          if (!(tVal > 0)) return;
          const pos = core.mapBarHeightPx(tVal, env, chartPxHeight, { mode: 'mixed', scaleKind: 'dailyBar' });
          const tickLine = document.createElement('div');
          tickLine.className = 'model-usage-tick-line';
          tickLine.style.bottom = `${pos.height.toFixed(1)}px`;
          const tickLbl = document.createElement('span');
          tickLbl.className = 'model-usage-tick-lbl';
          const isOverflowTop = Boolean(env.overflow && tVal === lastTick);
          tickLbl.textContent = isOverflowTop ? `${formatCompactTokenCount(tVal)}+` : formatCompactTokenCount(tVal);
          tickLine.appendChild(tickLbl);
          gridWrap.appendChild(tickLine);
        });
        if (maxLblEl) {
          maxLblEl.textContent = (env.overflow && summary.maxDayTotal > 0)
            ? formatCompactTokenCount(summary.maxDayTotal)
            : '';
        }
      } else {
        gridWrap.style.display = 'flex';
        gridWrap.style.flexDirection = 'column';
        gridWrap.style.justifyContent = 'space-between';
        baseLines.forEach(gl => { gl.style.display = 'block'; });
        if (maxLblEl) {
          maxLblEl.textContent = summary.maxDayTotal > 0 ? formatCompactTokenCount(summary.maxDayTotal) : '';
        }
      }
    } else if (maxLblEl) {
      maxLblEl.textContent = summary.maxDayTotal > 0 ? formatCompactTokenCount(summary.maxDayTotal) : '';
    }

    const barsEl = el('model-usage-bars');
    const xaxisEl = el('model-usage-xaxis');
    const legendEl = el('model-usage-legend');
    const emptyEl = el('model-usage-empty');
    const chartWrap = el('model-usage-chart-wrap');

    const hasAnyData = summary.windowTotalTokens > 0;
    if (emptyEl) emptyEl.style.display = hasAnyData ? 'none' : 'block';
    if (chartWrap) chartWrap.style.display = hasAnyData ? 'block' : 'none';
    if (chartWrap) chartWrap.setAttribute('data-scale-mode', modelUsageScaleMode);
    if (chartWrap) chartWrap.setAttribute('data-scale-tier', env.tier || '');

    const isCompact30 = modelUsagePeriodDays === 30;
    if (barsEl) {
      if (isCompact30) barsEl.classList?.add('compact-30');
      else barsEl.classList?.remove('compact-30');
      barsEl.replaceChildren();
    }
    if (xaxisEl) {
      if (isCompact30) xaxisEl.classList?.add('compact-30');
      else xaxisEl.classList?.remove('compact-30');
      xaxisEl.replaceChildren();
    }

    const anchorIndices = isCompact30
      ? new Set([0, 7, 14, 21, 29])
      : new Set([0, 1, 2, 3, 4, 5, 6]);
    const focusKey = modelUsageHoveredKey || modelUsageLockedKey || null;

    summary.days.forEach((day, idx) => {
      if (barsEl) {
        const col = document.createElement('div');
        col.className = 'model-usage-col';
        col.setAttribute('data-date', day.date);
        col.setAttribute('data-tokens', String(day.total || 0));

        // 折叠长尾段并保持真实 Top 顺序（column-reverse 下 index 0 在零基线底部）
        const segList = [];
        let otherSegTok = 0;
        (day.segments || []).forEach(seg => {
          if (foldedKeys.has(seg.key)) {
            otherSegTok += Number(seg.tokens) || 0;
          } else {
            segList.push({ ...seg, value: Number(seg.tokens) || 0 });
          }
        });
        if (otherSegTok > 0) {
          segList.push({
            key: '__other_series__',
            label: t('modelsUsage.otherSeries'),
            color: '#71717a',
            tokens: otherSegTok,
            value: otherSegTok,
            pct: day.total > 0 ? (otherSegTok / day.total) * 100 : 0
          });
        }
        // 点击锁定单系列时将该系列移至 0 基线底部（数组首位）
        if (modelUsageLockedKey) {
          const lockIdx = segList.findIndex(s => s.key === modelUsageLockedKey);
          if (lockIdx > 0) {
            const [lockedSeg] = segList.splice(lockIdx, 1);
            segList.unshift(lockedSeg);
          }
        }

        if (day.total > 0 && summary.maxDayTotal > 0 && segList.length > 0) {
          const barInfo = typeof core.mapBarHeightPx === 'function'
            ? core.mapBarHeightPx(day.total, env, chartPxHeight, { mode: modelUsageScaleMode, linearMax: summary.maxDayTotal, scaleKind: 'dailyBar' })
            : { height: Math.max(4, (day.total / summary.maxDayTotal) * chartPxHeight), overflow: false };
          const totalH = barInfo.height;
          const stack = document.createElement('div');
          stack.className = `model-usage-stack${barInfo.overflow && modelUsageScaleMode === 'mixed' ? ' is-overflow' : ''}`;
          stack.style.height = `${totalH.toFixed(4)}px`;
          stack.setAttribute('data-total-height', totalH.toFixed(4));

          const alloc = typeof core.allocateStackedSegmentHeights === 'function'
            ? core.allocateStackedSegmentHeights(segList, totalH, 1.5)
            : segList.map(s => ({ ...s, heightPx: (s.value / Math.max(1, day.total)) * totalH, rawRatio: s.value / Math.max(1, day.total) }));

          alloc.forEach(seg => {
            const segEl = document.createElement('div');
            segEl.className = `model-usage-seg${focusKey && seg.key !== focusKey ? ' is-dimmed' : ''}`;
            segEl.setAttribute('data-series-key', seg.key);
            segEl.setAttribute('data-raw-pct', (seg.rawRatio * 100).toFixed(2));
            segEl.style.height = `${seg.heightPx.toFixed(4)}px`;
            segEl.style.background = seg.color;
            stack.appendChild(segEl);
          });
          col.appendChild(stack);
        } else {
          const emptyBar = document.createElement('div');
          emptyBar.className = 'model-usage-empty-bar';
          col.appendChild(emptyBar);
        }

        const showBarPop = () => {
          const hp = el('heat-pop');
          const hpDate = el('heat-pop-date');
          const hpVal = el('heat-pop-val');
          const hpDet = el('heat-pop-det');
          if (!hp || !hpDate || !hpVal || !hpDet) return;
          hpDate.textContent = day.date + (day.date === todayStr ? t('heat.today') : '');
          hpVal.textContent = day.total > 0 ? `${formatCompactTokenCount(day.total)} Tokens` : '0 Tokens';
          hpDet.replaceChildren();
          if (day.segments.length > 0) {
            hpDet.style.display = 'flex';
            hpDet.style.flexDirection = 'column';
            hpDet.style.gap = '3px';
            day.segments.slice(0, 6).forEach(seg => {
              const row = document.createElement('div');
              row.style.display = 'flex';
              row.style.justifyContent = 'space-between';
              row.style.alignItems = 'center';
              row.style.gap = '10px';
              row.style.fontSize = '10.5px';
              const left = document.createElement('span');
              left.style.display = 'inline-flex';
              left.style.alignItems = 'center';
              left.style.gap = '5px';
              const dot = document.createElement('span');
              dot.style.display = 'inline-block';
              dot.style.width = '6px';
              dot.style.height = '6px';
              dot.style.borderRadius = '999px';
              dot.style.background = seg.color;
              const nm = document.createElement('span');
              nm.textContent = seg.label;
              left.appendChild(dot);
              left.appendChild(nm);
              const right = document.createElement('span');
              right.textContent = `${formatCompactTokenCount(seg.tokens)} (${Math.round(seg.pct * 10) / 10}%)`;
              row.appendChild(left);
              row.appendChild(right);
              hpDet.appendChild(row);
            });
          } else {
            hpDet.style.display = 'none';
          }
          const r = col.getBoundingClientRect();
          hp.style.left = `${r.left + r.width / 2}px`;
          hp.style.top = `${r.top - 6}px`;
          hp.style.opacity = '1';
        };
        col.addEventListener('mouseenter', showBarPop);
        col.addEventListener('mouseleave', hidePopover);
        col.addEventListener('click', showBarPop);
        barsEl.appendChild(col);
      }

      if (xaxisEl) {
        const lbl = document.createElement('div');
        lbl.className = 'model-usage-xlabel';
        lbl.textContent = anchorIndices.has(idx) ? formatModelDateShort(day.date) : '';
        xaxisEl.appendChild(lbl);
      }
    });

    if (legendEl) {
      legendEl.replaceChildren();
      effectiveLegend.forEach(item => {
        const card = document.createElement('div');
        card.className = `model-legend-item${focusKey && item.key !== focusKey ? ' is-dimmed' : ''}${modelUsageLockedKey === item.key ? ' is-locked' : ''}`;
        card.setAttribute('data-series-key', item.key);
        const bar = document.createElement('div');
        bar.className = 'model-legend-bar';
        bar.style.background = item.color;

        const textWrap = document.createElement('div');
        textWrap.className = 'model-legend-text';

        const nameEl = document.createElement('div');
        nameEl.className = 'model-legend-name';
        nameEl.textContent = item.label;
        nameEl.title = item.label;

        const valRow = document.createElement('div');
        valRow.className = 'model-legend-val-row';

        const pctEl = document.createElement('span');
        pctEl.className = 'model-legend-pct';
        pctEl.textContent = item.pctLabel;

        const metaEl = document.createElement('span');
        metaEl.className = 'model-legend-meta';
        metaEl.textContent = `${formatCompactTokenCount(item.tokens)} · ${t('modelsUsage.stepsSuffix', { n: item.steps })}`;

        valRow.appendChild(pctEl);
        valRow.appendChild(metaEl);
        textWrap.appendChild(nameEl);
        textWrap.appendChild(valRow);
        card.appendChild(bar);
        card.appendChild(textWrap);

        card.addEventListener('mouseenter', () => {
          modelUsageHoveredKey = item.key;
          applyModelSeriesFocusHighlight();
        });
        card.addEventListener('mouseleave', () => {
          if (modelUsageHoveredKey === item.key) modelUsageHoveredKey = null;
          applyModelSeriesFocusHighlight();
        });
        card.addEventListener('click', () => {
          modelUsageLockedKey = (modelUsageLockedKey === item.key) ? null : item.key;
          renderModelUsageView();
        });
        legendEl.appendChild(card);
      });
    }
  }

  let reqLogStatusFilter = 'all'; // 'all' | 'success' | 'error'
  let reqLogSortBy = defaultViewPrefs.reqLogSortBy;
  let reqLogPageLimit = 50;
  let reqLogLastRenderedSig = '';
  let lastRequestsLiveSyncAt = 0;

  // Antigravity 彩色静态矢量图标（构建期由 assets/antigravity-color.svg 离线内嵌）
  const AG_METER_AGENT_SVG_DATA_URI = '__AG_ANTIGRAVITY_COLOR_SVG_DATA_URI__';

  function createAntigravityAgentIcon() {
    const wrap = document.createElement('span');
    wrap.className = 'req-agent-icon';
    wrap.setAttribute('aria-hidden', 'true');
    const img = document.createElement('img');
    img.src = AG_METER_AGENT_SVG_DATA_URI;
    img.width = 14;
    img.height = 14;
    img.alt = 'Antigravity';
    img.style.cssText = 'width:100%;height:100%;object-fit:contain;display:block;background:transparent;';
    wrap.appendChild(img);
    return wrap;
  }

  function formatReqCompactTokens(val) {
    if (val == null || !Number.isFinite(Number(val))) return '—';
    const n = Math.max(0, Number(val));
    if (n >= 1e9) return `${(n / 1e9).toFixed(1)}B`;
    if (n >= 1e6) return `${(n / 1e6).toFixed(1)}M`;
    if (n >= 1000) return `${(n / 1000).toFixed(1)}K`;
    return String(Math.round(n));
  }

  function formatReqCacheHit(rec) {
    const inp = Math.max(0, Number(rec?.inputTokens || 0));
    const cache = Math.max(0, Number(rec?.cacheReadTokens || 0));
    const totalIn = inp + cache;
    if (totalIn <= 0) return '—';
    const rawPct = rec?.cacheReadPct != null && Number.isFinite(Number(rec.cacheReadPct))
      ? Number(rec.cacheReadPct)
      : ((cache / totalIn) * 100);
    if (rawPct <= 0) return '0%';
    const rounded1 = Math.round(rawPct * 10) / 10;
    if (rounded1 >= 100) return '100%';
    if (Math.abs(rounded1 - Math.round(rounded1)) < 0.05) return `${Math.round(rounded1)}%`;
    if (rounded1 >= 99) return `${rounded1.toFixed(1)}%`;
    return `${Math.round(rounded1)}%`;
  }

  function formatReqCost(rec) {
    let isPriced = Boolean(rec?.isPriced && rec.costUSD != null && Number.isFinite(Number(rec.costUSD)));
    let usd = isPriced ? Math.max(0, Number(rec.costUSD)) : null;
    if (!isPriced && rec && typeof calculateRequestApiCost === 'function') {
      const calc = calculateRequestApiCost(rec);
      if (calc?.isPriced && calc.costUSD != null && Number.isFinite(Number(calc.costUSD))) {
        isPriced = true;
        usd = Math.max(0, Number(calc.costUSD));
      }
    }
    if (!isPriced || usd == null) {
      return { text: '—', unpriced: true, tooltip: '' };
    }
    const text = usd >= 10 ? ('$' + usd.toFixed(2)) : ('$' + usd.toFixed(3));
    const tooltip = typeof formatUsdMetricTooltip === 'function' ? formatUsdMetricTooltip(usd) : text;
    return { text, unpriced: false, tooltip };
  }

  function formatReqDurationSec(sec) {
    if (sec == null || !Number.isFinite(Number(sec)) || Number(sec) <= 0) return '—';
    const s = Number(sec);
    if (s >= 60) {
      const m = Math.floor(s / 60);
      const rem = Math.round(s % 60);
      return t('reqLog.unit.minSec', { m, s: rem });
    }
    const val = s < 10 ? String(Number(s.toFixed(1))) : String(Math.round(s));
    return t('reqLog.unit.sec', { val });
  }

  function getReqDurationToneClass(sec) {
    if (sec == null || !Number.isFinite(Number(sec)) || Number(sec) <= 0) return '';
    const s = Number(sec);
    if (s < 8) return 'req-dur-fast';
    if (s < 20) return 'req-dur-mid';
    return 'req-dur-slow';
  }

  function resolveReqSpeedDisplayInfo(rec) {
    if (!rec) return { text: '—', tooltip: '', calculable: false, rawSpeed: null, e2eSortValue: null, hasValidE2e: false, source: 'unavailable', reasonCode: 'missing_record', isShortStream: false, streamingDetail: null };
    const tableFn = typeof resolveRequestTableSpeed === 'function' ? resolveRequestTableSpeed : window?.__AGContextMeterCore?.resolveRequestTableSpeed;
    if (typeof tableFn === 'function') {
      const tInfo = tableFn(rec);
      const hasValid = Boolean(tInfo?.hasValidE2e && Number.isFinite(tInfo?.endToEndTps) && tInfo.endToEndTps > 0);
      if (hasValid) {
        const displayVal = Number(tInfo.endToEndTps.toFixed(1));
        const parts = [];
        const sd = tInfo.streamingDetail;
        if (sd && sd.status === 'short_sample' && sd.rawStreamingSec != null) {
          parts.push(t('reqLog.speedShortNote', { sec: Number(Number(sd.rawStreamingSec).toFixed(4)) }));
        } else {
          parts.push(t('reqLog.speedOverallNote'));
        }
        return {
          text: t('reqLog.unit.tps', { val: displayVal }),
          tooltip: parts.join(' · '),
          calculable: true,
          rawSpeed: tInfo.e2eSortValue ?? tInfo.endToEndTps,
          e2eSortValue: tInfo.e2eSortValue ?? tInfo.endToEndTps,
          hasValidE2e: true,
          source: 'e2e',
          reasonCode: null,
          isShortStream: Boolean(sd && sd.status === 'short_sample'),
          streamingDetail: sd || null
        };
      }
      const rCode = tInfo?.e2eReasonCode || 'missing_duration';
      return {
        text: '—',
        tooltip: t(`reqLog.speedReason.${rCode}`),
        calculable: false,
        rawSpeed: null,
        e2eSortValue: null,
        hasValidE2e: false,
        source: 'unavailable',
        reasonCode: rCode,
        isShortStream: Boolean(tInfo?.streamingDetail?.status === 'short_sample'),
        streamingDetail: tInfo?.streamingDetail || null
      };
    }
    const info = typeof resolveRequestRowSpeed === 'function'
      ? resolveRequestRowSpeed(rec)
      : null;
    if (!info) return { text: '—', tooltip: '', calculable: false, rawSpeed: null, e2eSortValue: null, hasValidE2e: false, source: 'unavailable', reasonCode: 'missing_record', isShortStream: false, streamingDetail: null };
    if (info.calculable && info.speed != null && Number.isFinite(info.speed) && info.speed > 0) {
      const displayVal = Number(info.speed.toFixed(1));
      let tooltip = '';
      if (info.isShortStream && info.streamingSec != null) {
        tooltip = t('reqLog.speedShortNote', { sec: Number(Number(info.streamingSec).toFixed(4)) });
      } else if (info.source === 'overall') {
        tooltip = t('reqLog.speedOverallNote');
      }
      return {
        text: t('reqLog.unit.tps', { val: displayVal }),
        tooltip,
        calculable: true,
        rawSpeed: info.rawSpeed ?? info.speed,
        e2eSortValue: info.e2eSortValue ?? info.rawSpeed ?? info.speed,
        hasValidE2e: Boolean(info.hasValidE2e ?? info.calculable),
        source: info.source,
        reasonCode: null,
        isShortStream: Boolean(info.isShortStream),
        streamingDetail: info.streamingDetail || null
      };
    }
    const reasonKey = info.reasonCode ? `reqLog.speedReason.${info.reasonCode}` : 'reqLog.speedReason.missing_duration';
    return {
      text: '—',
      tooltip: t(reasonKey),
      calculable: false,
      rawSpeed: null,
      e2eSortValue: null,
      hasValidE2e: false,
      source: info.source || 'unavailable',
      reasonCode: info.reasonCode || 'missing_duration',
      isShortStream: false,
      streamingDetail: info.streamingDetail || null
    };
  }

  function formatReqSpeed(rec) {
    return resolveReqSpeedDisplayInfo(rec).text;
  }

  function resolveReqStatusInfo(rec) {
    const out = String(rec?.outcomeStatus || '').toLowerCase();
    const isStreaming = rec?.status === 'streaming' || out === 'streaming';
    if (isStreaming) {
      return { cls: 'is-streaming', label: t('reqLog.status.streaming'), isError: false, isStreaming: true };
    }
    if (!rec?.error && (!out || out === 'success' || out === 'final')) {
      return { cls: 'is-ok', label: t('reqLog.status.success'), isError: false, isStreaming: false };
    }
    if (out === 'exceeded') return { cls: 'is-err', label: t('reqLog.status.exceeded'), isError: true, isStreaming: false };
    if (out === 'rate_limited') return { cls: 'is-err', label: t('reqLog.status.rateLimited'), isError: true, isStreaming: false };
    if (out === 'quota_exhausted') return { cls: 'is-err', label: t('reqLog.status.quotaExhausted'), isError: true, isStreaming: false };
    if (out === 'network' || out === 'service_unavailable') return { cls: 'is-err', label: t('reqLog.status.network'), isError: true, isStreaming: false };
    if (out === 'auth_error') return { cls: 'is-err', label: t('reqLog.status.authError'), isError: true, isStreaming: false };
    if (out === 'canceled') return { cls: 'is-err', label: t('reqLog.status.canceled'), isError: true, isStreaming: false };
    return { cls: 'is-err', label: t('reqLog.status.failed'), isError: true, isStreaming: false };
  }

  function formatReqRequestedModel(rec, actualInfo = null) {
    if (!rec) return { text: '—', tooltip: '' };
    const configs = state.cascadeModelConfigs || state.scan?.cascadeModelConfigs || [];
    const avail = state.scan?.userStatus?.availableModels || null;
    const rawCand = rec.requestedModel || rec.requestedModelRaw || null;
    if (!rawCand) return { text: '—', tooltip: '' };
    const meta = typeof resolveRequestedModelDisplay === 'function'
      ? resolveRequestedModelDisplay(rawCand, configs, avail)
      : { text: String(rawCand), rawId: String(rawCand), stableId: null };
    const dispText = meta.text || '—';
    const tipParts = [];
    const rawOrigin = rec.requestedModelRaw || meta.rawId || '';
    if (rawOrigin && rawOrigin !== dispText) {
      tipParts.push(t('reqLog.requestedRawTip', { raw: rawOrigin }));
    }
    if (dispText !== '—' && actualInfo?.text && actualInfo.text !== '—') {
      const normReq = typeof normalizeModelId === 'function' ? (normalizeModelId(meta.stableId || dispText) || dispText.toLowerCase()) : dispText.toLowerCase();
      const normAct = typeof normalizeModelId === 'function' ? (normalizeModelId(actualInfo.text) || actualInfo.text.toLowerCase()) : actualInfo.text.toLowerCase();
      if (normReq && normAct && normReq !== normAct) {
        tipParts.push(t('reqLog.requestedDiffTip', { req: dispText, act: actualInfo.text }));
      }
    }
    return { text: dispText, tooltip: tipParts.join(' · ') };
  }

  function formatReqActualModel(rec) {
    if (!rec) return { text: '—', tooltip: '' };
    const cleanId = (v) => {
      const s = String(v || '').trim();
      if (!s || s === 'unattributed' || /^model_placeholder_/i.test(s) || /^unknown$/i.test(s)) return '';
      return s;
    };
    const key = cleanId(rec.modelKey);
    const exact = cleanId(rec.modelExactId);
    const rawM = cleanId(rec.model);
    const displayText = key || exact || rawM || (typeof formatCallModelTitle === 'function' ? formatCallModelTitle(rec) : '—');
    const tipParts = [];
    if (rec.modelLabel) tipParts.push(rec.modelLabel);
    if (rec.effort) tipParts.push(rec.effort);
    if (exact && exact !== displayText) tipParts.push(exact);
    else if (displayText && displayText !== '—' && !tipParts.length) tipParts.push(displayText);
    return { text: displayText || '—', tooltip: tipParts.join(' · ') };
  }

  function formatReqLocalYmd(d) {
    const dt = d instanceof Date ? d : new Date(d || Date.now());
    const pad2 = n => String(n).padStart(2, '0');
    return `${dt.getFullYear()}-${pad2(dt.getMonth() + 1)}-${pad2(dt.getDate())}`;
  }

  function formatReqTimeParts(rec) {
    const rawTs = Number(rec?.timestamp) || (rec?.created_at ? Date.parse(rec.created_at) : NaN);
    if (!Number.isFinite(rawTs) || rawTs <= 0) return { text: '—', tooltip: '', dateKey: rec?.date || '' };
    const d = new Date(rawTs);
    const pad2 = n => String(n).padStart(2, '0');
    const hhmmss = `${pad2(d.getHours())}:${pad2(d.getMinutes())}:${pad2(d.getSeconds())}`;
    const ymd = `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
    return { text: hhmmss, tooltip: `${ymd} ${hhmmss}`, dateKey: ymd };
  }

  function resolveReqProviderDisplay(rec) {
    const baseText = t('reqLog.provider.localSession');
    const tipParts = [baseText];
    if (rec?.accountScopeKey) {
      const ovAccts = Array.isArray(accountsUiState?.overview?.accounts) ? accountsUiState.overview.accounts : [];
      const found = ovAccts.find(a => a?.accountScopeKey === rec.accountScopeKey);
      if (found?.maskedEmail) tipParts.push(found.maskedEmail);
    }
    if (rec?.cascadeId) tipParts.push(`#${String(rec.cascadeId).slice(0, 8)}`);
    return { text: baseText, tooltip: tipParts.join(' · ') };
  }

  function buildLiveCallOverlayRecord(rawCall, fallbackScopeKey) {
    if (!rawCall || typeof rawCall !== 'object') return null;
    const inp = Math.max(0, Number(rawCall.inputTokens ?? 0) || 0);
    const cache = Math.max(0, Number(rawCall.cacheReadTokens ?? rawCall.cacheTokens ?? 0) || 0);
    const outp = Math.max(0, Number(rawCall.outputTokens ?? 0) || 0);
    const tot = inp + cache + outp;
    const isStreaming = rawCall.status === 'streaming' || rawCall.outcomeStatus === 'streaming';
    if (tot <= 0 && !rawCall.error && !isStreaming) return null;
    const ts = Number(rawCall.timestamp) || (rawCall.created_at ? Date.parse(rawCall.created_at) : Date.now());
    const ttftSec = (rawCall.ttftSec != null && Number.isFinite(Number(rawCall.ttftSec)) && Number(rawCall.ttftSec) >= 0)
      ? Number(Number(rawCall.ttftSec).toFixed(4))
      : null;
    const streamingSec = (rawCall.streamingSec != null && Number.isFinite(Number(rawCall.streamingSec)) && Number(rawCall.streamingSec) >= 0)
      ? Number(Number(rawCall.streamingSec).toFixed(4))
      : null;
    let durationSec = (rawCall.durationSec != null && Number.isFinite(Number(rawCall.durationSec)) && Number(rawCall.durationSec) > 0)
      ? Number(Number(rawCall.durationSec).toFixed(4))
      : ((ttftSec !== null && streamingSec !== null) ? Number((ttftSec + streamingSec).toFixed(4)) : (streamingSec || ttftSec || null));
    if (isStreaming && durationSec == null && Number.isFinite(ts)) {
      const liveElapsed = (Date.now() - ts) / 1000;
      if (liveElapsed > 0 && liveElapsed < 3600) durationSec = Number(liveElapsed.toFixed(4));
    }
    const tps = (rawCall.tps != null && Number.isFinite(Number(rawCall.tps)) && Number(rawCall.tps) > 0)
      ? Number(Number(rawCall.tps).toFixed(1))
      : ((outp > 0 && durationSec > 0) ? Number((outp / durationSec).toFixed(1)) : null);
    const streamingTps = (rawCall.streamingTps != null && Number.isFinite(Number(rawCall.streamingTps)) && Number(rawCall.streamingTps) > 0)
      ? Number(Number(rawCall.streamingTps).toFixed(1))
      : ((outp > 0 && streamingSec != null && streamingSec > 0) ? Number((outp / streamingSec).toFixed(1)) : null);
    const configsList = state.cascadeModelConfigs || state.scan?.cascadeModelConfigs || [];
    const availMap = state.scan?.userStatus?.availableModels || null;
    const reqMeta = typeof resolveRequestedModelDisplay === 'function'
      ? resolveRequestedModelDisplay(rawCall.requestedModel || rawCall.requestedModelRaw || null, configsList, availMap)
      : { text: rawCall.requestedModel ? String(rawCall.requestedModel) : null, rawId: rawCall.requestedModelRaw || null };
    const totalIn = inp + cache;
    const cacheReadPct = totalIn > 0 ? Number(((cache / totalIn) * 100).toFixed(1)) : null;
    let isPriced = Boolean(rawCall.isPriced);
    let costUSD = isPriced && Number.isFinite(Number(rawCall.costUSD)) ? Number(rawCall.costUSD) : null;
    let modelKey = rawCall.modelKey || null;
    if (!isPriced && typeof calculateRequestApiCost === 'function' && (rawCall.model || rawCall.modelExactId || modelKey) && tot > 0) {
      const calc = calculateRequestApiCost({
        ...rawCall,
        inputTokens: inp,
        cacheReadTokens: cache,
        cacheTokens: cache,
        outputTokens: outp,
        totalTokens: tot
      });
      if (calc?.isPriced) {
        isPriced = true;
        costUSD = Number(calc.costUSD || 0);
        if (!modelKey && calc.modelKey) modelKey = calc.modelKey;
      }
    }
    return {
      callId: rawCall.callId || null,
      cascadeId: rawCall.cascadeId || state.route || null,
      stepIndex: Number.isInteger(rawCall.stepIndex) ? rawCall.stepIndex : null,
      timestamp: Number.isFinite(ts) && ts > 0 ? ts : Date.now(),
      created_at: rawCall.created_at || new Date(Number.isFinite(ts) && ts > 0 ? ts : Date.now()).toISOString(),
      date: rawCall.date || formatReqLocalYmd(new Date(Number.isFinite(ts) && ts > 0 ? ts : Date.now())),
      source: rawCall.source === 'cli' ? 'cli' : (rawCall.source === 'ide' ? 'ide' : 'desktop'),
      agentRole: rawCall.agentRole || 'main',
      subagentType: rawCall.subagentType || null,
      requestedModel: reqMeta?.text || null,
      ...(reqMeta?.rawId && reqMeta.rawId !== reqMeta.text ? { requestedModelRaw: reqMeta.rawId } : (rawCall.requestedModelRaw ? { requestedModelRaw: rawCall.requestedModelRaw } : {})),
      model: rawCall.model || rawCall.modelExactId || modelKey || '',
      modelExactId: rawCall.modelExactId || null,
      modelKey: modelKey || (typeof normalizeModelId === 'function' ? normalizeModelId(rawCall.modelExactId || rawCall.model || '') : null),
      modelLabel: rawCall.modelLabel || null,
      effort: rawCall.effort || null,
      accountScopeKey: rawCall.accountScopeKey || fallbackScopeKey || null,
      inputTokens: inp,
      cacheReadTokens: cache,
      outputTokens: outp,
      thinkingTokens: Math.max(0, Number(rawCall.thinkingTokens || 0) || 0),
      totalTokens: tot,
      cacheReadPct,
      costUSD,
      isPriced,
      ttftSec,
      streamingSec,
      durationSec,
      tps,
      streamingTps,
      status: isStreaming ? 'streaming' : 'final',
      outcomeStatus: rawCall.outcomeStatus || (rawCall.error ? 'failed' : (isStreaming ? 'streaming' : 'success')),
      error: rawCall.error ? String(rawCall.error).slice(0, 200) : null
    };
  }

  function collectMergedRequestLogs() {
    const byId = new Map();
    const stepKeyToId = new Map();
    const makeStepLookupKey = (rec) => {
      if (!rec || !rec.cascadeId || !Number.isInteger(rec.stepIndex) || rec.stepIndex < 0) return '';
      return `${rec.source || 'desktop'}:${String(rec.cascadeId).toLowerCase()}#${rec.stepIndex}`;
    };
    const persisted = Array.isArray(ANTIGRAVITY_TOKEN_DATA.recentRequestLogs) ? ANTIGRAVITY_TOKEN_DATA.recentRequestLogs : [];
    for (const r of persisted) {
      if (!r || typeof r !== 'object') continue;
      const k = String(r.callId || `${r.source || 'desktop'}:${r.cascadeId || ''}:${r.stepIndex ?? ''}:${r.timestamp || 0}`);
      byId.set(k, r);
      const sk = makeStepLookupKey(r);
      if (sk && !stepKeyToId.has(sk)) stepKeyToId.set(sk, k);
    }

    const curAcctScope = ANTIGRAVITY_TOKEN_DATA.rawPayload?.accountScopeKey || accountsUiState?.overview?.activeAccountScopeKey || null;
    if (Array.isArray(state.sessionCalls) && state.sessionCalls.length > 0) {
      for (const raw of state.sessionCalls) {
        const liveRec = buildLiveCallOverlayRecord(raw, curAcctScope);
        if (!liveRec) continue;
        let k = String(liveRec.callId || `${liveRec.source}:${liveRec.cascadeId || ''}:${liveRec.stepIndex ?? ''}:${liveRec.timestamp}`);
        let prev = byId.get(k);
        if (!prev) {
          const sk = makeStepLookupKey(liveRec);
          const mappedKey = sk ? stepKeyToId.get(sk) : null;
          if (mappedKey && byId.has(mappedKey)) {
            const cand = byId.get(mappedKey);
            const candIsFallback = String(cand?.callId || '').includes('#');
            const liveIsFallback = String(liveRec.callId || '').includes('#');
            const sameUsage = Number(cand?.inputTokens || 0) === Number(liveRec.inputTokens || 0)
              && Number(cand?.outputTokens || 0) === Number(liveRec.outputTokens || 0);
            if (candIsFallback || liveIsFallback || sameUsage) {
              prev = cand;
              if (candIsFallback && !liveIsFallback && liveRec.callId) {
                byId.delete(mappedKey);
                stepKeyToId.set(sk, k);
              } else {
                k = mappedKey;
              }
            }
          }
        }
        if (!prev) {
          byId.set(k, liveRec);
          const sk = makeStepLookupKey(liveRec);
          if (sk && !stepKeyToId.has(sk)) stepKeyToId.set(sk, k);
        } else {
          // 合并实时流式或更完整数据，不丢已有账号归属与计时
          byId.set(k, {
            ...prev,
            ...liveRec,
            callId: (!String(prev.callId || '').includes('#') && prev.callId) ? prev.callId : (liveRec.callId || prev.callId),
            accountScopeKey: prev.accountScopeKey || liveRec.accountScopeKey || null,
            ttftSec: liveRec.ttftSec ?? prev.ttftSec ?? null,
            streamingSec: liveRec.streamingSec ?? prev.streamingSec ?? null,
            durationSec: liveRec.durationSec ?? prev.durationSec ?? null,
            tps: liveRec.tps ?? prev.tps ?? null,
            streamingTps: liveRec.streamingTps ?? prev.streamingTps ?? null,
            requestedModel: liveRec.requestedModel || prev.requestedModel || null,
            requestedModelRaw: liveRec.requestedModelRaw || prev.requestedModelRaw || null,
            modelKey: liveRec.modelKey || prev.modelKey || null,
            modelExactId: liveRec.modelExactId || prev.modelExactId || null,
            modelLabel: liveRec.modelLabel || prev.modelLabel || null
          });
        }
      }
    }

    if (state.livePendingRequest && state.route && state.livePendingRequest.cascadeId === state.route) {
      const isQueuedWait = state.livePendingRequest.stage === 'queued';
      const refStartedAt = Number(state.livePendingRequest.dispatchedAtMs || state.livePendingRequest.startedAtMs || 0);
      const elapsedSec = (!isQueuedWait && refStartedAt > 0)
        ? Math.max(0.1, Number(((Date.now() - refStartedAt) / 1000).toFixed(4)))
        : null;
      const hasNewStreaming = Array.from(byId.values()).some(
        r => r.cascadeId === state.route && r.status === 'streaming' && r.callId !== state.livePendingRequest.baselineCallId
      );
      if (!hasNewStreaming && !isQueuedWait && refStartedAt > 0) {
        const activeModel = state.latest?.model || state.selectedModelId || '';
        const trackedReq = state.lastRequestedModelByCascade?.get?.(state.route)?.requestedModel || null;
        const pendingKey = `__live_pending_${state.route}_${refStartedAt}`;
        byId.set(pendingKey, {
          callId: pendingKey,
          cascadeId: state.route,
          stepIndex: null,
          timestamp: refStartedAt,
          created_at: new Date(refStartedAt).toISOString(),
          date: formatReqLocalYmd(new Date(refStartedAt)),
          source: 'desktop',
          agentRole: 'main',
          subagentType: null,
          requestedModel: trackedReq,
          model: activeModel,
          modelExactId: activeModel || null,
          modelKey: typeof normalizeModelId === 'function' ? normalizeModelId(activeModel) : (activeModel || null),
          modelLabel: null,
          effort: null,
          accountScopeKey: curAcctScope,
          inputTokens: null,
          cacheReadTokens: null,
          outputTokens: null,
          thinkingTokens: 0,
          totalTokens: 0,
          cacheReadPct: null,
          costUSD: null,
          isPriced: false,
          ttftSec: elapsedSec,
          streamingSec: null,
          durationSec: elapsedSec,
          tps: null,
          streamingTps: null,
          status: 'streaming',
          outcomeStatus: 'streaming',
          error: null
        });
      }
    }

    const resolveReqTotalTokens = (rec) => (Number(rec?.inputTokens) || 0) + (Number(rec?.cacheReadTokens) || 0) + (Number(rec?.outputTokens) || 0);
    const reqSortMod = typeof window !== 'undefined' ? window.AGReqSortDropdown : null;
    const allRows = (reqSortMod && typeof reqSortMod.sortRequestRecords === 'function')
      ? reqSortMod.sortRequestRecords(Array.from(byId.values()), reqLogSortBy, {
        resolveSpeed: (rec) => resolveReqSpeedDisplayInfo(rec)
      })
      : Array.from(byId.values()).sort((a, b) => {
        const aStream = a.status === 'streaming' ? 1 : 0;
        const bStream = b.status === 'streaming' ? 1 : 0;
        if (bStream !== aStream) return bStream - aStream;
        const ta = Number(a.timestamp) || 0;
        const tb = Number(b.timestamp) || 0;
        if (reqLogSortBy === 'tokens_desc') {
          const diff = resolveReqTotalTokens(b) - resolveReqTotalTokens(a);
          if (diff !== 0) return diff;
        } else if (reqLogSortBy === 'cost_desc') {
          const diff = (Number(b.costUSD) || 0) - (Number(a.costUSD) || 0);
          if (Math.abs(diff) > 1e-12) return diff > 0 ? 1 : -1;
        } else if (reqLogSortBy === 'duration_desc') {
          const diff = (Number(b.durationSec) || 0) - (Number(a.durationSec) || 0);
          if (Math.abs(diff) > 1e-9) return diff > 0 ? 1 : -1;
        } else if (reqLogSortBy === 'speed_desc') {
          const sa = resolveReqSpeedDisplayInfo(a);
          const sb = resolveReqSpeedDisplayInfo(b);
          if (sb.calculable !== sa.calculable) return sb.calculable ? 1 : -1;
          const diff = (Number(sb.rawSpeed) || 0) - (Number(sa.rawSpeed) || 0);
          if (Math.abs(diff) > 1e-9) return diff > 0 ? 1 : -1;
        }
        if (tb !== ta) return tb - ta;
        return String(b.callId || '').localeCompare(String(a.callId || ''));
      });

    const filteredByScope = allRows.filter((rec) => {
      if (activeTokenSource === 'desktop' && rec.source !== 'desktop') return false;
      if (activeTokenSource === 'cli' && rec.source !== 'cli') return false;
      if (activeTokenAccountFilter === 'unattributed') {
        if (rec.accountScopeKey) return false;
      } else if (activeTokenAccountFilter !== 'all') {
        if (rec.accountScopeKey !== activeTokenAccountFilter) return false;
      }
      return true;
    });

    const filtered = filteredByScope.filter((rec) => {
      if (reqLogStatusFilter === 'all') return true;
      const st = resolveReqStatusInfo(rec);
      if (reqLogStatusFilter === 'success') return !st.isError;
      if (reqLogStatusFilter === 'error') return st.isError;
      return true;
    });

    return { totalInScope: filteredByScope.length, rows: filtered };
  }

  function renderRequestsLiveView({ force = false } = {}) {
    const viewEl = el('requests-live-view');
    const tbody = el('req-live-tbody');
    const emptyEl = el('req-live-empty');
    const summaryEl = el('req-live-summary');
    const moreWrap = el('req-live-more-wrap');
    const moreBtn = el('btn-req-live-more');
    if (!viewEl || !tbody) return;

    setPillActive(el('req-filter-all'), reqLogStatusFilter === 'all');
    setPillActive(el('req-filter-success'), reqLogStatusFilter === 'success');
    setPillActive(el('req-filter-error'), reqLogStatusFilter === 'error');
    el('req-sort-bar')?.querySelectorAll?.('[data-req-sort]').forEach(btn => {
      const active = btn.getAttribute('data-req-sort') === reqLogSortBy;
      setPillActive(btn, active);
      btn.setAttribute?.('aria-pressed', active ? 'true' : 'false');
    });

    const { totalInScope, rows } = collectMergedRequestLogs();
    const oReqVal = el('overflow-requests-val');
    if (oReqVal) oReqVal.textContent = rows.length > 0 ? String(rows.length) : '--';
    const todayStr = formatReqLocalYmd(new Date());
    const todayCount = rows.reduce((acc, r) => acc + ((r.date === todayStr || formatReqTimeParts(r).dateKey === todayStr) ? 1 : 0), 0);
    const limit = Math.max(20, Number(reqLogPageLimit) || 50);
    const visible = rows.slice(0, limit);
    const remaining = Math.max(0, rows.length - visible.length);

    const pricingCat = typeof getDynamicPricingCatalog === 'function' ? getDynamicPricingCatalog() : null;
    const sig = [
      currentPanelLanguage,
      activeTokenSource,
      activeTokenAccountFilter,
      reqLogStatusFilter,
      reqLogSortBy,
      limit,
      totalInScope,
      rows.length,
      todayCount,
      pricingCat?.updatedAt || '',
      pricingCat?.modelCount || 0,
      pricingCat?.customCount || 0,
      visible.slice(0, 6).map(r => `${r.callId || ''}:${r.status}:${r.outcomeStatus}:${r.requestedModel || ''}:${r.inputTokens}:${r.outputTokens}:${r.streamingSec}:${r.streamingTps}:${r.durationSec}:${r.costUSD}`).join(',')
    ].join('|');

    if (!force && sig === reqLogLastRenderedSig) return;
    reqLogLastRenderedSig = sig;

    if (summaryEl) {
      summaryEl.textContent = reqLogStatusFilter === 'all'
        ? t('reqLog.summary', { total: rows.length, today: todayCount })
        : t('reqLog.summaryFiltered', { shown: rows.length, total: totalInScope });
    }

    tbody.replaceChildren();
    if (!visible.length) {
      if (emptyEl) emptyEl.style.display = 'block';
      if (moreWrap) moreWrap.style.display = 'none';
      return;
    }
    if (emptyEl) emptyEl.style.display = 'none';

    for (const rec of visible) {
      const tr = document.createElement('tr');
      const statusInfo = resolveReqStatusInfo(rec);
      if (statusInfo.isStreaming) tr.className = 'is-streaming';

      // 1. 时间
      const timeInfo = formatReqTimeParts(rec);
      const tdTime = document.createElement('td');
      tdTime.className = 'req-td-time';
      tdTime.textContent = timeInfo.text;
      if (timeInfo.tooltip) tdTime.title = timeInfo.tooltip;
      tr.appendChild(tdTime);

      // 2. AGENT
      const tdAgent = document.createElement('td');
      const agentWrap = document.createElement('span');
      agentWrap.className = 'req-agent-cell';
      agentWrap.appendChild(createAntigravityAgentIcon());
      const agentLbl = document.createElement('span');
      agentLbl.textContent = rec.source === 'cli' ? 'Antigravity CLI' : (rec.source === 'ide' ? 'Antigravity IDE' : 'Antigravity');
      agentWrap.appendChild(agentLbl);
      if (rec.agentRole === 'subagent') {
        tdAgent.title = rec.subagentType ? `${t('reqLog.tipSubagent')} (${rec.subagentType})` : t('reqLog.tipSubagent');
      }
      tdAgent.appendChild(agentWrap);
      tr.appendChild(tdAgent);

      const modelInfo = formatReqActualModel(rec);

      // 3. 请求模型
      const reqModelInfo = formatReqRequestedModel(rec, modelInfo);
      const tdReqModel = document.createElement('td');
      tdReqModel.className = reqModelInfo.text !== '—' ? 'req-td-model' : 'req-td-muted';
      tdReqModel.textContent = reqModelInfo.text;
      if (reqModelInfo.tooltip) tdReqModel.title = reqModelInfo.tooltip;
      tr.appendChild(tdReqModel);

      // 4. 供应商 · 账号
      const provInfo = resolveReqProviderDisplay(rec);
      const tdProv = document.createElement('td');
      tdProv.className = 'req-td-provider';
      tdProv.textContent = provInfo.text;
      if (provInfo.tooltip) tdProv.title = provInfo.tooltip;
      tr.appendChild(tdProv);

      // 5. 实际模型
      const tdModel = document.createElement('td');
      tdModel.className = 'req-td-model';
      tdModel.textContent = modelInfo.text;
      if (modelInfo.tooltip) tdModel.title = modelInfo.tooltip;
      tr.appendChild(tdModel);

      // 6. 输入
      const tdIn = document.createElement('td');
      tdIn.className = 'req-td-num';
      tdIn.textContent = formatReqCompactTokens(rec.inputTokens);
      if (rec.inputTokens != null) {
        const cacheVal = Math.max(0, Number(rec.cacheReadTokens || 0));
        tdIn.title = t('reqLog.tipInputBreakdown', {
          inp: fmt(rec.inputTokens),
          cache: fmt(cacheVal),
          total: fmt(Number(rec.inputTokens) + cacheVal)
        });
      }
      tr.appendChild(tdIn);

      // 7. 输出
      const tdOut = document.createElement('td');
      tdOut.className = 'req-td-num';
      tdOut.textContent = formatReqCompactTokens(rec.outputTokens);
      if (rec.outputTokens != null && rec.thinkingTokens > 0) {
        tdOut.title = t('reqLog.tipOutputBreakdown', {
          out: fmt(rec.outputTokens),
          think: fmt(rec.thinkingTokens)
        });
      }
      tr.appendChild(tdOut);

      // 8. 缓存命中率
      const tdCache = document.createElement('td');
      tdCache.className = 'req-td-num';
      tdCache.textContent = formatReqCacheHit(rec);
      tr.appendChild(tdCache);

      // 9. 费用
      const costInfo = formatReqCost(rec);
      const tdCost = document.createElement('td');
      tdCost.className = `req-td-cost${costInfo.unpriced ? ' is-unpriced' : ''}`;
      tdCost.textContent = costInfo.text;
      if (costInfo.tooltip) tdCost.title = costInfo.tooltip;
      tr.appendChild(tdCost);

      // 10. 首字耗时
      const tdTtft = document.createElement('td');
      tdTtft.className = 'req-td-num';
      tdTtft.textContent = formatReqDurationSec(rec.ttftSec);
      tr.appendChild(tdTtft);

      // 11. 耗时
      const durTone = getReqDurationToneClass(rec.durationSec);
      const tdDur = document.createElement('td');
      tdDur.className = `req-td-num${durTone ? ` ${durTone}` : ''}`;
      tdDur.textContent = formatReqDurationSec(rec.durationSec);
      tr.appendChild(tdDur);

      // 12. 速度
      const tdSpd = document.createElement('td');
      const spdInfo = resolveReqSpeedDisplayInfo(rec);
      tdSpd.className = spdInfo.calculable ? 'req-td-num' : 'req-td-num req-td-muted';
      tdSpd.textContent = spdInfo.text;
      if (spdInfo.tooltip) tdSpd.title = spdInfo.tooltip;
      if (!spdInfo.calculable && spdInfo.reasonCode) tdSpd.setAttribute('data-speed-reason', spdInfo.reasonCode);
      tr.appendChild(tdSpd);

      // 13. 状态
      const tdStatus = document.createElement('td');
      const stWrap = document.createElement('span');
      stWrap.className = `req-status-cell ${statusInfo.cls}`;
      const stDot = document.createElement('span');
      stDot.className = 'req-status-dot';
      stDot.setAttribute('aria-hidden', 'true');
      const stTxt = document.createElement('span');
      stTxt.textContent = statusInfo.label;
      stWrap.appendChild(stDot);
      stWrap.appendChild(stTxt);
      if (rec.error) tdStatus.title = rec.error;
      tdStatus.appendChild(stWrap);
      tr.appendChild(tdStatus);

      tbody.appendChild(tr);
    }

    if (moreWrap && moreBtn) {
      if (remaining > 0) {
        moreWrap.style.display = 'flex';
        moreBtn.textContent = t('reqLog.loadMore', { n: remaining });
      } else {
        moreWrap.style.display = 'none';
      }
    }
  }


  // =========================================================================
  // 输入栏紧凑状态条 (Composer Status Bar) 与 5 行悬停卡
  // =========================================================================
  function computeSessionCacheHitSummarySafe(calls) {
    const cacheFn = typeof computeCacheHitSummary === 'function' ? computeCacheHitSummary : core?.computeCacheHitSummary;
    if (cacheFn) return cacheFn(calls);
    let u = 0, cr = 0, outp = 0, hasData = false, hasDenom = false;
    for (const c of (Array.isArray(calls) ? calls : [])) {
      if (!c || typeof c !== 'object') continue;
      const cc = Math.max(0, Number(c.cacheCreationInputTokens ?? c.cache_creation_input_tokens ?? 0) || 0);
      const inp = Math.max(0, Number(c.inputTokens ?? c.input_tokens ?? c.input ?? 0) || 0) + cc;
      const crv = Math.max(0, Number(c.cacheReadTokens ?? c.cacheTokens ?? c.cache_read_tokens ?? c.cached ?? 0) || 0);
      const ov = Math.max(0, Number(c.outputTokens ?? c.output_tokens ?? c.output ?? 0) || 0);
      if (inp > 0 || crv > 0 || ov > 0) hasData = true;
      if (inp + crv > 0) hasDenom = true;
      u += inp;
      cr += crv;
      outp += ov;
    }
    const ti = u + cr;
    const hitRatio = hasDenom && ti > 0 ? Math.max(0, Math.min(1, cr / ti)) : null;
    const hitPct = hitRatio !== null ? Math.round(hitRatio * 100) : null;
    return {
      hasRealUsageData: hasData,
      uncachedInput: u,
      cacheRead: cr,
      totalInput: ti,
      output: outp,
      grandTotal: ti + outp,
      hitRatio,
      hitPct,
      cacheHitPct: hitPct,
      cacheStatus: !hasData ? 'missing' : (ti <= 0 ? 'missing' : (cr > 0 ? 'hit' : 'zero'))
    };
  }

  function resolveSessionCacheHitDisplay(calls = state.sessionCalls) {
    const summary = computeSessionCacheHitSummarySafe(calls);
    if (summary?.hitRatio === null || summary?.hitRatio === undefined || !Number.isFinite(Number(summary.hitRatio))) {
      return '--';
    }
    const pctVal = Math.max(0, Math.min(100, Number(summary.hitRatio) * 100));
    if (pctVal <= 0) return '0%';
    if (pctVal >= 99.95) return '100%';
    return `${pctVal.toFixed(1)}%`;
  }

  /**
   * 计算单个会话窗格的输入框底栏指标（完全限定于该窗格自身数据与自身 DOM 节点，绝不跨窗格串值）。
   */
  function computeComposerBarMetricsForData(paneData, scopeDomRoot = null) {
    const data = paneData || resolveSessionDataForPane(state.route, true);
    const paneCalls = Array.isArray(data.sessionCalls) ? data.sessionCalls : [];
    const paneTimeline = data.sessionTimeline || null;
    const paneScan = data.scan || null;
    const paneStats = data.sessionStats || null;
    const paneLatest = data.latest || null;

    let detectedDomTurns = 0;
    try {
      const rootNode = scopeDomRoot || (typeof document !== 'undefined' ? document : null);
      if (rootNode && typeof rootNode.querySelectorAll === 'function') {
        const userMsgEls = rootNode.querySelectorAll(
          '[data-testid*="user-message"], [data-role="user"], .user-message, div.items-end > div.rounded-2xl, div.items-end > div[class*="rounded"]'
        );
        if (userMsgEls && userMsgEls.length > 0) detectedDomTurns = userMsgEls.length;
      }
    } catch { }

    let maxCallTurn = 0;
    let maxCallStep = 0;
    for (const c of paneCalls) {
      if (!c) continue;
      const ti = Number(c.turnIndex ?? c.turn_index);
      const si = Number(c.stepIndex ?? c.step_index);
      if (Number.isInteger(ti) && ti >= 0) maxCallTurn = Math.max(maxCallTurn, ti + 1);
      if (Number.isInteger(si) && si >= 0) maxCallStep = Math.max(maxCallStep, si + 1);
    }

    const turnsFromTimeline = Array.isArray(paneTimeline?.turns) ? paneTimeline.turns.length : 0;
    const turnsFromAll = Array.isArray(data.allTurns) ? data.allTurns.length : 0;
    const turnsFromScan = Number(paneScan?.session?.userMessages || 0);
    const turnsFromStats = Number(paneStats?.turnCount || 0);
    const turnsCount = Math.max(turnsFromTimeline, turnsFromAll, turnsFromScan, maxCallTurn, detectedDomTurns, turnsFromStats);

    const stepsFromScan = Number(paneScan?.session?.steps || 0);
    const callsCount = paneCalls.length;
    const stepsFromStats = Number(paneStats?.stepCount || 0);
    const stepsCount = Math.max(stepsFromScan, maxCallStep, callsCount, stepsFromStats);

    const hasTurnsData = Boolean(
      turnsFromTimeline > 0 || turnsFromAll > 0 || turnsFromScan > 0 || maxCallTurn > 0 || detectedDomTurns > 0 || paneStats?.turnCount != null
    );
    const hasStepsData = Boolean(
      stepsFromScan > 0 || maxCallStep > 0 || callsCount > 0 || paneStats?.stepCount != null
    );

    const latestCallRec = paneCalls.length ? paneCalls[paneCalls.length - 1] : null;
    const lastCallSpeed = latestCallRec
      ? (speedDisplayMode === 'e2e'
        ? (latestCallRec.tps ?? latestCallRec.overallTps ?? latestCallRec.streamingTps ?? null)
        : (latestCallRec.streamingTps ?? latestCallRec.tps ?? null))
      : null;
    const speedCandidate = data.lastSpeedEval?.tps
      ?? data.lastSpeedEval?.streamingTps
      ?? data.liveSpeed?.tps
      ?? paneLatest?.speed?.tps
      ?? data.speedOverrideForTest?.tps
      ?? lastCallSpeed
      ?? null;
    const isPendingWait = Boolean(data.livePendingRequest && (!data.sessionId || sameRouteId(data.livePendingRequest.cascadeId, data.sessionId)));
    const isPendingQueued = Boolean(isPendingWait && data.livePendingRequest.stage === 'queued');
    const hasSpeedVal = speedCandidate !== null && speedCandidate !== undefined && Number.isFinite(Number(speedCandidate)) && Number(speedCandidate) >= 0;
    const isRemoteSpeedUnavailable = !hasSpeedVal && data.lastSpeedEval?.phase === 'remote_unavailable';
    const speedStr = hasSpeedVal
      ? `${Number(speedCandidate).toFixed(0)} tok/s`
      : (isRemoteSpeedUnavailable
        ? (data.lastSpeedEval?.badge?.text || '远程对话')
        : (isPendingQueued ? t('composer.speedQueued') : (isPendingWait ? t('composer.speedWaiting') : '—')));

    const speedDisplayText = (data.loading && turnsCount === 0 && stepsCount === 0)
      ? t('badge.reading')
      : t('composer.speedTurns', {
        turns: hasTurnsData ? turnsCount : '—',
        steps: hasStepsData ? stepsCount : '—',
        speed: speedStr
      });

    // 2. 会话 Token 用量与缓存命中率（保留真实 0%，缺失显示 —）
    const csSummary = computeSessionCacheHitSummarySafe(paneCalls);
    let hasRealUsageData = csSummary.hasRealUsageData;
    let uncachedInput = csSummary.uncachedInput;
    const cacheRead = csSummary.cacheRead;
    const output = csSummary.output;
    let totalInput = csSummary.totalInput;
    let grandTotal = csSummary.grandTotal;
    let hitPct = csSummary.cacheHitPct;
    if (!hasRealUsageData && paneStats) {
      const su = Number(paneStats.usedTokens || 0);
      if (su > 0) {
        hasRealUsageData = true;
        uncachedInput = su;
        totalInput = su;
        grandTotal = su;
        hitPct = null;
      }
    }
    const hitPctStr = hitPct !== null ? `${hitPct}%` : '—';
    const compactTokensVal = hasRealUsageData ? formatReqCompactTokens(grandTotal) : '—';
    const tokenCacheText = t('composer.tokenCache', {
      tokens: compactTokensVal,
      hit: hitPctStr
    });
    const tokenCacheTip = t('composer.tokenCacheTitle', {
      tokens: hasRealUsageData ? `${compactTokensVal} tok` : '—',
      hit: hitPctStr
    });

    // 3. 上下文占用
    const rawUsed = paneLatest?.actual ?? paneLatest?.postCompactEstimate ?? paneLatest?.estimate ?? paneStats?.usedTokens ?? data.tokenUsage?.used ?? null;
    const usedTok = rawUsed !== null && rawUsed !== undefined && Number.isFinite(Number(rawUsed)) && Number(rawUsed) >= 0 ? Number(rawUsed) : null;
    const rawLimit = paneLatest?.budget ?? paneStats?.limitTokens ?? data.tokenUsage?.limit ?? null;
    const limitTok = rawLimit !== null && rawLimit !== undefined && Number.isFinite(Number(rawLimit)) && Number(rawLimit) > 0 ? Number(rawLimit) : null;
    const limitSource = data.customContextLimit ? '用户设置' : (limitTok !== null ? '设置' : '—');
    const pct = usedTok !== null && limitTok !== null ? Math.min(100, Math.max(0, Math.round((usedTok / limitTok) * 100))) : null;
    const pctText = pct !== null ? `${pct}%` : '--%';
    const limitStr = limitTok !== null ? `${formatReqCompactTokens(limitTok)} · ${limitSource}` : '—';
    const ctxTip = pct !== null
      ? t('composer.card.contextTooltip', {
        used: formatReqCompactTokens(usedTok),
        limit: limitStr,
        remaining: formatReqCompactTokens(Math.max(0, limitTok - usedTok))
      })
      : `上下文 · ${usedTok !== null ? formatReqCompactTokens(usedTok) : '—'} / ${limitTok !== null ? formatReqCompactTokens(limitTok) : '—'}`;

    // 4. 4 态运行状态机
    const isCompactingNow = Boolean(data.compacting && (!data.sessionId || sameRouteId(data.compacting.cascadeId, data.sessionId)));
    const curSelectedModel = (data.isActiveRoute ? state.selectedModelId : '') || paneLatest?.model || '';
    const lastCallModel = latestCallRec?.model || latestCallRec?.modelExactId || '';
    const detectFamily = (m) => {
      const s = String(m || '').toLowerCase();
      if (s.includes('claude')) return 'claude';
      if (s.includes('gemini')) return 'gemini';
      if (s.includes('gpt') || s.includes('o1') || s.includes('o3')) return 'openai';
      return s ? s.split(/[-_\s]/)[0] : '';
    };
    const compactCrossModel = Boolean(
      isCompactingNow && curSelectedModel && lastCallModel && detectFamily(curSelectedModel) && detectFamily(lastCallModel) && detectFamily(curSelectedModel) !== detectFamily(lastCallModel)
    );
    const refDispMs = Number(data.livePendingRequest?.dispatchedAtMs || data.livePendingRequest?.startedAtMs || 0);
    const waitSec = (!isPendingQueued && isPendingWait && refDispMs > 0)
      ? Math.max(0, (Date.now() - refDispMs) / 1000)
      : 0;
    const isGeneratingNow = Boolean((isPendingWait && !isPendingQueued) || (latestCallRec && String(latestCallRec.status || '').toLowerCase() === 'streaming'));
    const isOfflineNow = typeof navigator !== 'undefined' && navigator.onLine === false;
    const lastErrMsg = paneLatest?.error ? String(paneLatest.error) : (data.requestError ? String(data.requestError) : '');
    const isUserCancel = Boolean(paneLatest?.canceled || /cancel|abort/i.test(lastErrMsg));

    const runtimeStatus = isPendingQueued
      ? { state: 'running', reasonCode: 'queued', label: t('composer.runtime.reason.queued'), detail: '' }
      : (typeof evaluateSessionRuntimeStatus === 'function'
        ? evaluateSessionRuntimeStatus({
          isGenerating: isGeneratingNow,
          waitSec,
          isCompacting: isCompactingNow,
          compactCrossModel,
          lastError: lastErrMsg,
          isUserCanceled: isUserCancel,
          isOffline: isOfflineNow
        })
        : { state: 'idle', reasonCode: 'ready', label: '就绪', detail: '' });

    const RUNTIME_REASON_I18N = {
      ready: 'composer.runtime.reason.ready',
      generating: 'composer.runtime.reason.generating',
      queued: 'composer.runtime.reason.queued',
      compacting: 'composer.runtime.reason.compacting',
      slow_wait: 'composer.runtime.reason.slow_wait',
      compact_kv_recompute: 'composer.runtime.reason.compact_kv_recompute',
      retrying: 'composer.runtime.reason.retrying',
      reconnecting: 'composer.runtime.reason.reconnecting',
      disconnected: 'composer.runtime.reason.disconnected',
      offline: 'composer.runtime.reason.offline',
      request_error: 'composer.runtime.reason.request_error'
    };
    const RUNTIME_STATE_I18N = {
      idle: 'composer.runtime.idle',
      running: 'composer.runtime.running',
      slow: 'composer.runtime.slow',
      error: 'composer.runtime.error'
    };
    const reasonKey = RUNTIME_REASON_I18N[runtimeStatus.reasonCode] || RUNTIME_STATE_I18N[runtimeStatus.state] || 'composer.runtime.idle';
    const runtimeLabel = t(reasonKey) || runtimeStatus.label;

    return {
      turnsCount, stepsCount, hasTurnsData, hasStepsData,
      speedStr, speedDisplayText, isRemoteSpeedUnavailable,
      hasRealUsageData, uncachedInput, cacheRead, output, totalInput, grandTotal,
      hitPct, hitPctStr, compactTokensVal, tokenCacheText, tokenCacheTip,
      usedTok, limitTok, pct, pctText, ctxTip, latestCallRec,
      runtimeStatus, runtimeLabel, compactCrossModel
    };
  }

  /**
   * 渲染单个非焦点会话窗格的独立克隆状态条（每个窗格各自读取自身会话数据，极窄时优先保留本会话缓存与用量）。
   */
  function renderPaneCloneStatusBar(pane) {
    const bar = pane?.statusBarEl;
    if (!bar || bar.id === 'composer-status-bar') return;
    const paneData = resolveSessionDataForPane(pane.sessionId, false);
    if (!paneData.hydrated && pane.sessionId) {
      syncBackgroundSplitPaneSessions();
    }
    const m = computeComposerBarMetricsForData(paneData, pane.paneEl);

    let hostWidth = 0;
    try {
      const pr = bar.parentElement?.getBoundingClientRect?.();
      if (pr && Number.isFinite(pr.width) && pr.width > 0) hostWidth = pr.width;
    } catch { }
    const widthMode = hostWidth > 0 && hostWidth < 500
      ? 'tight'
      : (hostWidth > 0 && hostWidth < 680 ? 'narrow' : 'normal');
    bar.setAttribute?.('data-csb-width', widthMode);
    bar.setAttribute?.('data-ag-csb-session-id', pane.sessionId || '');

    const dot = bar.querySelector?.('[data-csb-role="status-dot"]');
    const rtText = bar.querySelector?.('[data-csb-role="runtime-text"]');
    const statusGroup = bar.querySelector?.('[data-csb-group="status"]');
    if (dot) dot.className = `csb-status-dot is-${m.runtimeStatus.state}`;
    if (rtText) rtText.textContent = m.runtimeLabel;
    if (statusGroup) {
      statusGroup.setAttribute('data-runtime-state', m.runtimeStatus.state);
      statusGroup.setAttribute('data-tooltip', `${t('composer.runtime.title')}: ${m.runtimeLabel}`);
    }

    const speedTxt = bar.querySelector?.('[data-csb-role="speed-text"]');
    const speedGroup = bar.querySelector?.('[data-csb-group="speed"]');
    if (speedTxt) speedTxt.textContent = m.speedDisplayText;
    if (speedGroup) speedGroup.setAttribute('data-tooltip', m.speedDisplayText);

    const tokTxt = bar.querySelector?.('[data-csb-role="tokens-text"]');
    const tokGroup = bar.querySelector?.('[data-csb-group="tokens"]');
    if (tokTxt) tokTxt.textContent = m.tokenCacheText;
    if (tokGroup) tokGroup.setAttribute('data-tooltip', m.tokenCacheTip);

    const ctxTxt = bar.querySelector?.('[data-csb-role="context-text"]');
    const ctxGroup = bar.querySelector?.('[data-csb-group="context"]');
    if (ctxTxt) ctxTxt.textContent = m.pctText;
    if (ctxGroup) ctxGroup.setAttribute('data-tooltip', m.ctxTip);

    // 账号额度为账号级共享数据，在非极窄窗格中按需显示；极窄窗格优先保证本会话缓存与用量可读
    const quotaBtn = bar.querySelector?.('[data-csb-group="quota"]');
    const quotaTxt = bar.querySelector?.('[data-csb-role="quota-text"]');
    if (quotaBtn && quotaTxt) {
      const q5 = el('csb-quota-text-5h')?.textContent || '';
      const q7 = el('csb-quota-text-7d')?.textContent || '';
      const qSingle = el('csb-quota-text-single')?.textContent || '';
      const parts = [];
      if (q5 && el('csb-quota-5h') && !el('csb-quota-5h').hidden) parts.push(q5);
      if (widthMode !== 'tight' && q7 && el('csb-quota-7d') && !el('csb-quota-7d').hidden) parts.push(q7);
      if (!parts.length && qSingle && el('csb-quota-single') && !el('csb-quota-single').hidden) parts.push(qSingle);
      if (showComposerQuotaSummary && parts.length > 0 && el('csb-group-quota') && !el('csb-group-quota').hidden) {
        quotaBtn.hidden = false;
        quotaTxt.textContent = parts.join(' · ');
      } else {
        quotaBtn.hidden = true;
      }
    }
  }

  function renderComposerStatusBar() {
    const csbBar = el('composer-status-bar');
    if (!csbBar) return;
    if (state.route && (state.latest || state.scan || state.sessionCalls?.length)) {
      saveSessionSnapshotToCache(state.route);
    }
    const mountedPanes = ensureComposerStatusBarMounted() || [];
    syncComposerStatusBarWidth();

    const primaryPane = mountedPanes.find(p => p.isFocused) || null;
    const primaryData = resolveSessionDataForPane(primaryPane?.sessionId || state.route, true);
    const m = computeComposerBarMetricsForData(primaryData, primaryPane?.paneEl || null);

    // 1. 组 1: 轮次/步数与速度
    const speedTextEl = el('csb-speed-text');
    if (speedTextEl) speedTextEl.textContent = m.speedDisplayText;
    const speedGroupEl = el('csb-group-speed');
    if (speedGroupEl) {
      const remoteComment = m.isRemoteSpeedUnavailable && primaryData.lastSpeedEval?.comment
        ? ` · ${primaryData.lastSpeedEval.comment}`
        : '';
      speedGroupEl.setAttribute('data-tooltip', `${speedTextEl?.textContent || '速度与轮步'}${remoteComment}`);
      speedGroupEl.title = '';
    }

    // 2. 组 2: 会话 Token 用量与缓存命中率
    const tokensGroupEl = el('csb-group-tokens');
    if (tokensGroupEl) {
      tokensGroupEl.setAttribute('data-tooltip', m.tokenCacheTip);
      tokensGroupEl.title = '';
    }
    const tokensTextEl = el('csb-tokens-text');
    if (tokensTextEl) tokensTextEl.textContent = m.tokenCacheText;

    // 5 行卡片数值
    const tflTotal = el('tfl-val-total');
    const tflHit = el('tfl-val-hit');
    const tflUncached = el('tfl-val-uncached');
    const tflCached = el('tfl-val-cached');
    const tflOutput = el('tfl-val-output');
    if (tflTotal) tflTotal.textContent = m.hasRealUsageData ? `${m.grandTotal.toLocaleString()} tok` : '—';
    if (tflHit) tflHit.textContent = m.hitPctStr;
    if (tflUncached) tflUncached.textContent = m.hasRealUsageData ? `${m.uncachedInput.toLocaleString()} tok` : '—';
    if (tflCached) tflCached.textContent = m.hasRealUsageData ? `${m.cacheRead.toLocaleString()} tok` : '—';
    if (tflOutput) tflOutput.textContent = m.hasRealUsageData ? `${m.output.toLocaleString()} tok` : '—';

    // 3. 组 3: 上下文小圆环与百分比 + 4 段细分条 & 4 态运行状态机
    const ctxTextEl = el('csb-context-text');
    const ctxBtn = el('csb-group-context');
    const ctxCircleEl = el('csb-context-circle');
    if (ctxTextEl) ctxTextEl.textContent = m.pctText;
    if (ctxCircleEl) {
      const circumference = 53.4;
      const offset = m.pct !== null ? circumference * (1 - (m.pct / 100)) : circumference;
      ctxCircleEl.style.strokeDashoffset = String(Math.max(0, Number(offset.toFixed(1))));
    }
    if (ctxBtn) {
      ctxBtn.setAttribute('data-tooltip', m.ctxTip);
      ctxBtn.title = '';
    }

    // 4. 分段上下文构成 (新增 / 写缓存 / 读缓存 / 剩余) 与 75%/90% 阈值着色
    const latestCallRec = m.latestCallRec;
    const segUsage = latestCallRec ? {
      inputTokens: latestCallRec.inputTokens ?? 0,
      cacheCreationInputTokens: latestCallRec.cacheCreationInputTokens ?? latestCallRec.cache_creation_input_tokens ?? null,
      cacheReadTokens: latestCallRec.cacheReadTokens ?? latestCallRec.cacheTokens ?? 0,
      outputTokens: latestCallRec.outputTokens ?? 0,
      actual: m.usedTok ?? latestCallRec.totalTokens ?? 0
    } : { actual: m.usedTok ?? 0 };
    const segInfo = typeof computeContextSegments === 'function'
      ? computeContextSegments(segUsage, m.limitTok || 0)
      : null;

    const applySegmentBar = (freshEl, writeEl, readEl, barEl, legendEl) => {
      if (!segInfo || segInfo.usedTokens <= 0) {
        if (barEl && barEl.id === 'key-seg-track') barEl.hidden = true;
        if (legendEl && legendEl.id === 'key-seg-legend') legendEl.hidden = true;
        return;
      }
      if (barEl && barEl.id === 'key-seg-track') barEl.hidden = false;
      if (legendEl && legendEl.id === 'key-seg-legend') legendEl.hidden = false;
      if (barEl) barEl.setAttribute('data-threshold', segInfo.thresholdLevel);
      if (freshEl) freshEl.style.width = `${segInfo.freshPct}%`;
      if (writeEl) writeEl.style.width = `${segInfo.cacheWritePct}%`;
      if (readEl) readEl.style.width = `${segInfo.cacheReadPct}%`;
      if (legendEl) {
        if (typeof legendEl.replaceChildren === 'function') legendEl.replaceChildren();
        else legendEl.textContent = '';
        const appendLegendItem = (colorHex, labelText) => {
          const item = document.createElement('span');
          item.className = 'key-seg-legend-item';
          if (colorHex) {
            const sw = document.createElement('i');
            sw.className = 'key-seg-swatch';
            if (sw.style) sw.style.background = colorHex;
            item.appendChild(sw);
          }
          const txt = document.createElement('span');
          txt.textContent = labelText;
          item.appendChild(txt);
          legendEl.appendChild(item);
        };
        appendLegendItem('#38bdf8', t('composer.card.segFresh', { val: formatReqCompactTokens(segInfo.freshInputTokens) }));
        if (segInfo.hasCacheWrite && segInfo.cacheWriteTokens > 0) {
          appendLegendItem('#f59e0b', t('composer.card.segWrite', { val: formatReqCompactTokens(segInfo.cacheWriteTokens) }));
        }
        if (segInfo.cacheReadTokens > 0) {
          appendLegendItem('#34d399', t('composer.card.segRead', { val: formatReqCompactTokens(segInfo.cacheReadTokens) }));
        }
        if (segInfo.limitTokens > 0) {
          appendLegendItem('', t('composer.card.segRemain', { val: formatReqCompactTokens(segInfo.remainingTokens) }));
        }
      }
    };
    applySegmentBar(el('tfl-seg-fresh'), el('tfl-seg-write'), el('tfl-seg-read'), el('tfl-seg-bar'), el('tfl-seg-legend'));
    const effSubModeNow = state.ctxSubtrackMode || ((segInfo && segInfo.usedPct < 25) ? 'comp' : 'cache');
    if (effSubModeNow === 'cache') {
      applySegmentBar(el('key-seg-fresh'), el('key-seg-cache-write'), el('key-seg-cache-read'), el('key-seg-track'), el('key-seg-legend'));
    }
    const tflSegPct = el('tfl-seg-pct');
    if (tflSegPct) {
      const threshKey = segInfo?.thresholdLevel === 'critical'
        ? 'composer.threshold.critical'
        : (segInfo?.thresholdLevel === 'warning' ? 'composer.threshold.warning' : 'composer.threshold.normal');
      tflSegPct.textContent = segInfo && segInfo.limitTokens > 0
        ? `${segInfo.usedPct}% · ${t(threshKey)}`
        : '--%';
    }

    // 5. 运行状态
    const csbStatusGroup = el('csb-group-status');
    const csbDot = el('csb-runtime-dot');
    const csbRuntimeText = el('csb-runtime-text');
    if (csbStatusGroup) {
      csbStatusGroup.setAttribute('data-runtime-state', m.runtimeStatus.state);
      csbStatusGroup.setAttribute('data-tooltip', `${t('composer.runtime.title')}: ${m.runtimeLabel} · ${t('composer.runtime.clickHint')}`);
      csbStatusGroup.setAttribute('aria-label', `${t('composer.runtime.title')}: ${m.runtimeLabel} · ${t('composer.runtime.clickHint')}`);
      csbStatusGroup.title = '';
    }
    if (csbDot) csbDot.className = `csb-status-dot is-${m.runtimeStatus.state}`;
    if (csbRuntimeText) csbRuntimeText.textContent = m.runtimeLabel;
    const tflRuntimeNote = el('tfl-runtime-note');
    if (tflRuntimeNote) {
      if (m.runtimeStatus.state === 'slow' || m.runtimeStatus.state === 'error' || m.compactCrossModel) {
        tflRuntimeNote.hidden = false;
        tflRuntimeNote.setAttribute('data-level', m.runtimeStatus.state);
        tflRuntimeNote.textContent = currentPanelLanguage === 'en' ? m.runtimeLabel : (m.runtimeStatus.detail || m.runtimeLabel);
      } else {
        tflRuntimeNote.hidden = true;
        tflRuntimeNote.textContent = '';
      }
    }
    if (typeof renderComposerQuotaSummary === 'function') {
      renderComposerQuotaSummary(lastComputedQuotaView, Date.now());
    }
    const oCacheInline = el('overflow-cache-val');
    if (oCacheInline) {
      oCacheInline.textContent = resolveSessionCacheHitDisplay();
    }

    // 6. 同步渲染其余同屏会话窗格的独立底栏状态条（绝不串值）
    for (const pane of mountedPanes) {
      if (pane && pane !== primaryPane && pane.statusBarEl) {
        renderPaneCloneStatusBar(pane);
      }
    }
  }

  /**
   * 渲染每条助手回复与 Side Question 尾部的单行统计微徽标（受 showTurnFooterStats 控制）
   */
  function syncOverflowMenuMetrics() {
    try {
      const d = state.latest;
      const stale = state.requestError || (state.requestAt && Date.now() - state.requestAt > 20000);
      let pct = null;
      if (d?.exceeded) pct = 100;
      else if (d?.percent != null && !stale) pct = Math.min(100, Math.max(0, d.percent));
      else if (d?.actual != null && d?.budget && !stale) pct = Math.min(100, Math.max(0, (d.actual / d.budget) * 100));
      const oCtx = el('overflow-context-val');
      if (oCtx) oCtx.textContent = pct != null ? `${Math.round(pct)}%` : '--%';
      const oDetail = el('overflow-context-detail-val');
      if (oDetail) {
        const tl = state.sessionTimeline;
        const turnN = Array.isArray(tl?.turns) ? tl.turns.length : 0;
        const callN = Array.isArray(state.sessionCalls) ? state.sessionCalls.length : 0;
        oDetail.textContent = turnN > 0 ? `${turnN}轮` : (callN > 0 ? `${callN}次` : '--');
      }
      const oCache = el('overflow-cache-val');
      if (oCache) {
        oCache.textContent = resolveSessionCacheHitDisplay();
      }
      const oReq = el('overflow-requests-val');
      if (oReq) {
        const callN = Array.isArray(state.sessionCalls) ? state.sessionCalls.length : 0;
        oReq.textContent = callN > 0 ? String(callN) : '--';
      }
    } catch { }
  }

  function buildAuthoritativeMainTurns(sessionIdOverride = undefined, timelineOverride = undefined, callsOverride = undefined) {
    const useOverride = sessionIdOverride !== undefined || timelineOverride !== undefined || callsOverride !== undefined;
    const targetRoute = useOverride ? (sessionIdOverride || '') : (state.route || '');
    const tl = useOverride ? timelineOverride : state.sessionTimeline;
    const rawList = useOverride ? callsOverride : state.sessionCalls;
    const routeLower = targetRoute ? String(targetRoute).toLowerCase() : '';
    const timelineMatchesRoute = !routeLower || !tl?.cascadeId || String(tl.cascadeId).toLowerCase() === routeLower;
    if (timelineMatchesRoute && Array.isArray(tl?.turns) && tl.turns.length > 0) {
      const validTurns = [];
      for (const turn of tl.turns) {
        if (!turn) continue;
        const tCalls = Array.isArray(turn.calls) ? turn.calls.filter(c => c && c.agentRole !== 'subagent') : [];
        if (tCalls.length > 0) {
          validTurns.push({
            turnKey: `turn-${turn.turnIndex ?? turn.stepIndex ?? validTurns.length}`,
            turnIndex: turn.turnIndex,
            stepIndex: turn.stepIndex,
            isCompactionTurn: Boolean(turn.isCompactionTurn),
            compactionStatus: turn.compactionStatus || null,
            compactionRecord: turn.compactionRecord || null,
            timestamp: turn.timestamp || null,
            calls: tCalls
          });
        }
      }
      if (validTurns.length > 0) {
        return { source: 'timeline', turns: validTurns };
      }
    }
    const calls = (Array.isArray(rawList) ? rawList : []).filter(c => c && c.agentRole !== 'subagent');
    if (calls.length === 0) return { source: 'empty', turns: [] };
    if (typeof groupSessionCallsByTurns === 'function') {
      const grouped = groupSessionCallsByTurns([], calls, { cascadeId: targetRoute || null });
      const turns = (Array.isArray(grouped?.turns) ? grouped.turns : [])
        .filter(tr => Array.isArray(tr?.calls) && tr.calls.length > 0)
        .map((tr, idx) => ({
          turnKey: `fallback-${tr.turnIndex ?? idx}`,
          turnIndex: tr.turnIndex ?? idx + 1,
          stepIndex: tr.stepIndex ?? null,
          calls: tr.calls
        }));
      if (turns.length > 0) return { source: 'fallback', turns };
    }
    return {
      source: 'fallback',
      turns: [{ turnKey: `call-${calls[calls.length - 1]?.callId || 'latest'}`, turnIndex: 1, stepIndex: null, calls }]
    };
  }

  function desensitizeTurnCallId(callId) {
    const raw = String(callId || '').trim();
    if (!raw || raw === 'unknown') return '—';
    if (raw.length <= 12) return raw;
    return `${raw.slice(0, 4)}…${raw.slice(-4)}`;
  }

  const turnFooterScopeState = new Map();
  const compactFooterExpandedState = new Map();
  const COMPACT_FOOTER_STYLE_ID = 'ag-cm-compact-footer-style';

  function ensureCompactionFooterStyles() {
    try {
      if (typeof document === 'undefined' || !document.head) return;
      if (document.getElementById(COMPACT_FOOTER_STYLE_ID)) return;
      const st = document.createElement('style');
      st.id = COMPACT_FOOTER_STYLE_ID;
      st.textContent = `
        .ag-cm-turn-footer[data-ag-turn-footer-kind="compaction"] {
          cursor: pointer;
          font-weight: 500;
        }
        .ag-cm-compact-footer-detail {
          display: block;
          margin-top: 6px;
          padding: 6px 10px;
          border-radius: 7px;
          font-size: 11.5px;
          line-height: 1.45;
          color: var(--foreground, #d4d4d8);
          background: rgba(128, 128, 128, 0.10);
          border: 1px solid rgba(128, 128, 128, 0.22);
        }
        .ag-cm-compact-footer-detail[hidden] {
          display: none !important;
        }
      `;
      document.head.appendChild(st);
    } catch { }
  }

  function detectCompactionDomAnchorForToolbar(tb) {
    try {
      if (!tb) return false;
      const msgBlock = tb.closest?.('[data-message-id], [data-step-index], [data-turn-index], article, section')
        || tb.parentElement?.parentElement
        || tb.parentElement;
      const checkCompactEntityInNode = (node) => {
        if (!node || typeof node.querySelectorAll !== 'function') return false;
        const explicitCmd = node.querySelector?.('[data-slash-command="compact"], [data-command="compact"]');
        if (explicitCmd) return true;
        // 核对宿主实体 compact 命令胶囊：纯文本严格为 compact（或带折叠图标），排除普通长句里提到 compact
        const chips = Array.from(node.querySelectorAll('span, div, button') || []);
        for (const ch of chips) {
          if (!ch || ch.closest?.('.ag-cm-turn-footer, .ag-cm-compact-footer-detail')) continue;
          const childCnt = ch.childElementCount ?? (ch.children ? ch.children.length : 0);
          if (childCnt > 3) continue;
          const clean = String(ch.textContent || '').replace(/[\u200b-\u200d\ufeff\s]/g, '').toLowerCase();
          if (clean === 'compact' && (ch.querySelector?.('svg') || ch.getAttribute?.('data-lexical-decorator') === 'true')) {
            return true;
          }
        }
        const blockTxt = String(node.textContent || '');
        if (
          blockTxt.includes('The conversation was compacted')
          || blockTxt.includes('会话已被压缩以适应上下文窗口')
          || blockTxt.includes('工作階段已被壓縮以適應上下文視窗')
        ) {
          return true;
        }
        return false;
      };
      if (checkCompactEntityInNode(msgBlock)) return true;
      let prev = msgBlock?.previousElementSibling || null;
      for (let i = 0; i < 3 && prev; i++) {
        if (prev.querySelector?.('[data-testid="cascade-system-message-toolbar"]')) break;
        if (checkCompactEntityInNode(prev)) return true;
        prev = prev.previousElementSibling || null;
      }
    } catch { }
    return false;
  }

  function resolveCompletedCompactionForTurn(tb, turnObj, sessionIdOverride = undefined, paneLatestOverride = undefined) {
    const explicitCompaction = Boolean(turnObj?.isCompactionTurn);
    const explicitStatus = String(turnObj?.compactionStatus || '').toLowerCase();
    if (explicitStatus === 'cancelled' || explicitStatus === 'failed' || explicitStatus === 'compacting') {
      return null;
    }
    const domAnchored = detectCompactionDomAnchorForToolbar(tb);
    const routeKey = String(sessionIdOverride !== undefined ? (sessionIdOverride || '') : (state.route || '')).trim();
    const activeRec = routeKey && typeof getCompactionProgressRecord === 'function'
      ? getCompactionProgressRecord(routeKey)
      : null;
    const histList = routeKey && typeof getCompactionHistoryForSession === 'function'
      ? getCompactionHistoryForSession(routeKey)
      : [];

    if (!explicitCompaction && !domAnchored) return null;

    // 若本轮关联的任务明确被取消或失败且无匹配已完成记录，绝不显示「压缩已完成」
    const callTs = Number(turnObj?.calls?.[turnObj.calls.length - 1]?.timestamp || turnObj?.timestamp || 0);
    if (turnObj?.compactionRecord && turnObj.compactionRecord.phase === 'completed') {
      return turnObj.compactionRecord;
    }
    const completedRecords = [];
    if (activeRec && activeRec.phase === 'completed') completedRecords.push(activeRec);
    for (const h of histList) {
      if (h && h.phase === 'completed' && !completedRecords.some(x => x.taskKey === h.taskKey)) {
        completedRecords.push(h);
      }
    }
    if (completedRecords.length > 0) {
      if (callTs > 0) {
        const matched = completedRecords.find(r => {
          const ref = Number(r.completedAtMs || r.startedAtMs || 0);
          return ref > 0 && Math.abs(ref - callTs) <= 180000;
        });
        if (matched) return matched;
      }
      return completedRecords[completedRecords.length - 1];
    }
    // 若当前唯一记录是明确取消/失败，绝不显示已完成
    if (activeRec && (activeRec.phase === 'cancelled' || activeRec.phase === 'failed') && !explicitCompaction) {
      return null;
    }
    const latestRef = paneLatestOverride !== undefined ? paneLatestOverride : state.latest;
    return {
      phase: 'completed',
      taskKey: String(turnObj?.turnKey || 'compact-turn'),
      beforeTokens: null,
      afterTokens: null,
      budget: latestRef?.budget ?? latestRef?.serviceLimit ?? null,
      checkpointIndexBefore: null,
      checkpointIndexAfter: null
    };
  }

  function renderTurnFooterStats() {
    try {
      if (typeof document?.querySelectorAll !== 'function') return;
      const existing = document.querySelectorAll('.ag-cm-turn-footer');
      const existingDetails = document.querySelectorAll('.ag-cm-compact-footer-detail');
      if (!showTurnFooterStats) {
        existing.forEach(n => n.remove?.());
        existingDetails.forEach(n => n.remove?.());
        return;
      }
      const rawCalls = Array.isArray(state.sessionCalls) ? state.sessionCalls : [];
      const visiblePanes = discoverVisibleSessionPanes();
      const isMultiPaneView = visiblePanes.length > 1;
      if (!isMultiPaneView && rawCalls.length === 0) {
        existing.forEach(n => n.remove?.());
        existingDetails.forEach(n => n.remove?.());
        return;
      }
      const rawToolbars = Array.from(document.querySelectorAll('[data-testid="cascade-system-message-toolbar"], [data-testid="side-question-tab-conversation"] [data-testid="cascade-system-message-toolbar"]'));
      const seenTb = new Set();
      const mainToolbars = [];
      const sideToolbars = [];
      for (const tb of rawToolbars) {
        if (!tb || seenTb.has(tb)) continue;
        seenTb.add(tb);
        const isSide = Boolean(
          tb.closest?.('[data-testid="side-question-tab-conversation"], [data-side-question], .side-question-container')
          || tb.getAttribute?.('data-side-question') === 'true'
        );
        if (isSide) sideToolbars.push(tb);
        else mainToolbars.push(tb);
      }
      if (mainToolbars.length === 0 && sideToolbars.length === 0) {
        existing.forEach(n => n.remove?.());
        existingDetails.forEach(n => n.remove?.());
        return;
      }

      const cacheFn = typeof computeCacheHitSummary === 'function' ? computeCacheHitSummary : core?.computeCacheHitSummary;
      // 读写分离：在修改任何 DOM 节点前一次性批量读取工具栏宽度，消除 M 轮历史回复上的强制同步回流 (Layout Thrashing)
      const toolbarWidths = new Map();
      for (let i = 0; i < mainToolbars.length; i++) {
        const tb = mainToolbars[i];
        const row = tb.firstElementChild || tb;
        toolbarWidths.set(tb, Number(row.clientWidth || tb.clientWidth || 0));
      }
      for (let s = 0; s < sideToolbars.length; s++) {
        const tb = sideToolbars[s];
        const row = tb.firstElementChild || tb;
        toolbarWidths.set(tb, Number(row.clientWidth || tb.clientWidth || 0));
      }
      const applyFooterToToolbar = (tb, turnObj, forceFallbackScope = false, paneSessionId = undefined, paneLatest = undefined) => {
        const row = tb.firstElementChild || tb;
        const removeOld = () => {
          const old = row.querySelector?.('.ag-cm-turn-footer') || tb.querySelector?.('.ag-cm-turn-footer');
          if (old) old.remove?.();
          const oldDetail = tb.querySelector?.('.ag-cm-compact-footer-detail');
          if (oldDetail) oldDetail.remove?.();
        };
        const sidKey = paneSessionId !== undefined ? String(paneSessionId || '') : String(state.route || '');
        const turnKey = String(turnObj?.turnKey || '');
        const scopedTurnKey = sidKey ? `${sidKey}::${turnKey}` : turnKey;
        const completedCompaction = resolveCompletedCompactionForTurn(tb, turnObj, paneSessionId, paneLatest);
        if (completedCompaction) {
          ensureCompactionFooterStyles();
          let badge = row.querySelector?.('.ag-cm-turn-footer') || null;
          if (!badge) {
            badge = document.createElement('span');
            badge.className = 'ag-cm-turn-footer';
            badge.setAttribute('data-ag-turn-footer', '1');
            badge.setAttribute('role', 'button');
            badge.tabIndex = 0;
            row.prepend ? row.prepend(badge) : row.appendChild?.(badge);
          }
          const detailKey = sidKey
            ? `${sidKey}::${String(completedCompaction.taskKey || turnKey || 'compact')}`
            : String(completedCompaction.taskKey || turnKey || 'compact');
          const expanded = compactFooterExpandedState.get(detailKey) === true;
          const compactLabel = t('turnFooter.compacted');
          badge.__turnObj = turnObj;
          badge.__compactionRec = completedCompaction;
          badge.__compactionDetailKey = detailKey;
          badge.__paneSessionId = paneSessionId;
          badge.__paneLatest = paneLatest;
          badge.__tb = tb;
          badge.setAttribute('data-ag-turn-footer-kind', 'compaction');
          badge.setAttribute('data-turn-key', turnKey || detailKey);
          if (sidKey) badge.setAttribute('data-ag-pane-session-id', sidKey);
          badge.setAttribute('aria-expanded', expanded ? 'true' : 'false');
          if (badge.textContent !== compactLabel) badge.textContent = compactLabel;
          const tipStr = t('turnFooter.compactTip');
          if (badge.title !== tipStr) badge.title = tipStr;
          if (badge.getAttribute('aria-label') !== `${compactLabel} · ${tipStr}`) {
            badge.setAttribute('aria-label', `${compactLabel} · ${tipStr}`);
          }

          let detailEl = tb.querySelector?.('.ag-cm-compact-footer-detail') || null;
          if (!detailEl) {
            detailEl = document.createElement('div');
            detailEl.className = 'ag-cm-compact-footer-detail';
            detailEl.setAttribute('data-ag-compact-footer-detail', detailKey);
            tb.appendChild?.(detailEl);
          }
          const bTok = Number(completedCompaction.beforeTokens);
          const aTok = Number(completedCompaction.afterTokens);
          const latestRef = paneLatest !== undefined ? paneLatest : state.latest;
          const bgt = Number(completedCompaction.budget || latestRef?.budget || latestRef?.serviceLimit || 0);
          const hasTrustedPair = Number.isFinite(bTok) && bTok > 0 && Number.isFinite(aTok) && aTok >= 0;
          const fmtOcc = (tok) => (bgt > 0 ? `${short(tok)} / ${short(bgt)} · ${((tok / bgt) * 100).toFixed(1)}%` : short(tok));
          const detailParts = [];
          if (hasTrustedPair) {
            detailParts.push(`${fmtOcc(bTok)} -> ${fmtOcc(aTok)}`);
            const relTok = Math.max(0, bTok - aTok);
            const relPct = ((relTok / bTok) * 100).toFixed(1);
            detailParts.push(t('turnFooter.compactReleased', { tok: short(relTok), pct: relPct }));
          } else {
            detailParts.push(t('turnFooter.compactStatsPending'));
          }
          const cpB = Number.isInteger(completedCompaction.checkpointIndexBefore) && completedCompaction.checkpointIndexBefore >= 0
            ? `#${completedCompaction.checkpointIndexBefore}`
            : '';
          const cpA = Number.isInteger(completedCompaction.checkpointIndexAfter) && completedCompaction.checkpointIndexAfter >= 0
            ? `#${completedCompaction.checkpointIndexAfter}`
            : '';
          if (cpB && cpA) detailParts.push(t('turnFooter.compactCheckpoint', { cp: `${cpB} -> ${cpA}` }));
          else if (cpA) detailParts.push(t('turnFooter.compactCheckpoint', { cp: cpA }));
          const detailText = detailParts.join(' · ');
          if (detailEl.textContent !== detailText) detailEl.textContent = detailText;
          detailEl.hidden = !expanded;

          if (!badge.__agClickBound) {
            badge.__agClickBound = true;
            badge.addEventListener('click', (ev) => {
              ev.stopPropagation?.();
              if (badge.getAttribute('data-ag-turn-footer-kind') === 'compaction') {
                const dk = badge.__compactionDetailKey || 'compact';
                const nextOpen = !(compactFooterExpandedState.get(dk) === true);
                compactFooterExpandedState.set(dk, nextOpen);
                applyFooterToToolbar(badge.__tb || tb, badge.__turnObj, badge.__forceFallback, badge.__paneSessionId, badge.__paneLatest);
                return;
              }
              const curObj = badge.__turnObj;
              if (!curObj || !Array.isArray(curObj.calls)) return;
              if (curObj.calls.length > 1) {
                const curScope = badge.getAttribute('data-scope') || 'turn';
                const nextScope = curScope === 'turn' ? 'request' : 'turn';
                const k = String(badge.__scopedTurnKey || curObj.turnKey || '');
                if (k) turnFooterScopeState.set(k, nextScope);
                applyFooterToToolbar(badge.__tb || tb, curObj, badge.__forceFallback, badge.__paneSessionId, badge.__paneLatest);
              } else {
                if (typeof openDashboardInRightPanel === 'function') void openDashboardInRightPanel();
              }
            });
            badge.addEventListener('dblclick', (ev) => {
              ev.stopPropagation?.();
              if (typeof openDashboardInRightPanel === 'function') void openDashboardInRightPanel();
            });
            badge.addEventListener('keydown', (ev) => {
              if (ev.key === 'Enter' || ev.key === ' ') {
                ev.preventDefault?.();
                ev.stopPropagation?.();
                badge.click();
              }
            });
          }
          return;
        }
        if (!turnObj || !Array.isArray(turnObj.calls) || turnObj.calls.length === 0) {
          removeOld();
          return;
        }
        const turnCalls = turnObj.calls;
        const lastCall = turnCalls[turnCalls.length - 1];
        if (!lastCall) {
          removeOld();
          return;
        }
        // 非压缩轮次清理可能残留的压缩详情节点并恢复普通尾标类型
        const staleCompactDetail = tb.querySelector?.('.ag-cm-compact-footer-detail');
        if (staleCompactDetail) staleCompactDetail.remove?.();
        const existingBadgeForNorm = row.querySelector?.('.ag-cm-turn-footer');
        if (existingBadgeForNorm) {
          existingBadgeForNorm.removeAttribute?.('data-ag-turn-footer-kind');
          existingBadgeForNorm.removeAttribute?.('aria-expanded');
        }
        const isMultiCall = !forceFallbackScope && turnCalls.length > 1;
        const requestedScope = isMultiCall ? (turnFooterScopeState.get(scopedTurnKey) || turnFooterScopeState.get(turnKey) || 'turn') : 'request';
        const isTurnAggregate = requestedScope === 'turn';
        const activeCalls = isTurnAggregate ? turnCalls : [lastCall];
        const cs = cacheFn
          ? cacheFn(activeCalls)
          : (() => {
            const inp = activeCalls.reduce((a, c) => a + Math.max(0, Number(c?.inputTokens || 0)) + Math.max(0, Number(c?.cacheCreationInputTokens ?? 0)), 0);
            const cr = activeCalls.reduce((a, c) => a + Math.max(0, Number(c?.cacheReadTokens ?? c?.cacheTokens ?? 0)), 0);
            const outp = activeCalls.reduce((a, c) => a + Math.max(0, Number(c?.outputTokens || 0)), 0);
            const ti = inp + cr;
            return {
              hasRealUsageData: ti > 0 || outp > 0,
              uncachedInput: inp,
              cacheRead: cr,
              totalInput: ti,
              output: outp,
              cacheHitPct: ti > 0 ? Math.round((cr / ti) * 100) : null
            };
          })();

        const hasCalcUsage = Boolean(cs.hasConfirmedUsage || cs.hasRealUsageData);
        const rawHitPct = cs.hitPct ?? cs.cacheHitPct ?? null;
        const scopeLabel = isTurnAggregate ? t('turnFooter.scopeTurn') : t('turnFooter.scopeReq');
        const hitStr = rawHitPct !== null ? `${rawHitPct}%` : '—';
        const resolveSingleCallModelName = (c) => {
          if (!c || typeof c !== 'object') return '';
          const direct = String(c.attributedModelLabel || c.modelLabel || '').trim();
          if (direct && !/^(未知|未知模型|unknown|unknown model)$/i.test(direct)) return direct;
          const rawId = String(c.modelExactId || c.modelRaw || c.model || '').trim();
          if (rawId && !/^(未知|未知模型|unknown|unknown model)$/i.test(rawId)) {
            if (typeof resolveModelDisplayName === 'function') {
              const mapped = String(resolveModelDisplayName(rawId) || '').trim();
              if (mapped && !/^(未知|未知模型|unknown|unknown model)$/i.test(mapped)) return mapped;
            }
            return rawId;
          }
          return '';
        };
        const resolveTurnFooterModelInfo = () => {
          const coreAttrFn = typeof window !== 'undefined' ? window.__AGContextMeterCore?.resolveTurnFooterModelAttribution : null;
          if (typeof coreAttrFn === 'function') {
            const attr = coreAttrFn(activeCalls, {
              isTurnAggregate,
              cascadeModelConfigs: state.cascadeModelConfigs,
              availableModels: state.modelCapabilitiesById
            });
            if (attr && attr.label) {
              return {
                label: attr.label,
                models: Array.isArray(attr.models) ? attr.models : [],
                unknownReason: String(attr.unknownReason || '')
              };
            }
          }
          if (!isTurnAggregate) {
            const single = resolveSingleCallModelName(lastCall);
            if (single) return { label: single, models: [single], unknownReason: '' };
            const rawMissing = String(lastCall.modelExactId || lastCall.modelRaw || lastCall.model || '').trim();
            return {
              label: t('quota.unknownModel') || '未知模型',
              models: [],
              unknownReason: rawMissing ? `未识别模型 ID: ${rawMissing}` : '该请求未返回可靠模型标识'
            };
          }
          // 本轮汇总：按真实子调用权重归属，避免末尾无模型名的辅助子调用把主模型挤成未知模型
          const weightByModel = new Map();
          let missingCount = 0;
          for (const c of activeCalls) {
            const resolved = resolveSingleCallModelName(c);
            if (!resolved) {
              missingCount += 1;
              continue;
            }
            const weight = Math.max(1, Number(c?.outputTokens || 0) * 4 + Number(c?.totalTokens || 0));
            weightByModel.set(resolved, (weightByModel.get(resolved) || 0) + weight);
          }
          const sortedModels = Array.from(weightByModel.entries()).sort((a, b) => b[1] - a[1]).map(x => x[0]);
          if (sortedModels.length === 1) {
            return {
              label: sortedModels[0],
              models: sortedModels,
              unknownReason: missingCount > 0 ? `另有 ${missingCount} 条辅助子调用缺模型字段` : ''
            };
          }
          if (sortedModels.length > 1) {
            const lastCallResolved = resolveModelDisplayName(lastCall);
            return {
              label: `多模型 · ${sortedModels[0]} · ${sortedModels.length}模型`,
              models: sortedModels,
              lastCallModel: lastCallResolved || '',
              unknownReason: ''
            };
          }
          return {
            label: '未知模型',
            models: [],
            unknownReason: '本轮全部请求均缺少可核验模型标识'
          };
        };
        const modelInfo = resolveTurnFooterModelInfo();
        const mName = modelInfo.label;
        let actualSpeedKind = speedDisplayMode === 'e2e' ? 'e2e' : 'streaming';
        let tpsNum = null;
        if (speedDisplayMode === 'e2e') {
          if (lastCall.tps != null) tpsNum = lastCall.tps;
          else if (lastCall.overallTps != null) tpsNum = lastCall.overallTps;
          else if (lastCall.streamingTps != null) { tpsNum = lastCall.streamingTps; actualSpeedKind = 'streaming'; }
        } else {
          if (lastCall.streamingTps != null) tpsNum = lastCall.streamingTps;
          else if (lastCall.tps != null) { tpsNum = lastCall.tps; actualSpeedKind = 'e2e'; }
        }
        const tpsStr = (tpsNum != null && Number.isFinite(Number(tpsNum)) && Number(tpsNum) > 0) ? `${Number(tpsNum).toFixed(0)} tok/s` : '';
        const inCompact = hasCalcUsage ? `In ${formatReqCompactTokens(cs.totalInput)}` : 'In —';
        const outCompact = hasCalcUsage ? `Out ${formatReqCompactTokens(cs.output)}` : 'Out —';
        const cacheCompact = `${t('turnFooter.cache')} ${hitStr}`;
        const taskQuotaCompact = (typeof resolveTurnTaskQuotaTag === 'function')
          ? resolveTurnTaskQuotaTag(turnObj, sidKey)
          : '';

        const rowW = toolbarWidths.has(tb) ? toolbarWidths.get(tb) : Number(row.clientWidth || tb.clientWidth || 0);
        let footerParts;
        if (rowW <= 0 || rowW >= 460) {
          footerParts = [scopeLabel, mName, inCompact, outCompact, cacheCompact, tpsStr, taskQuotaCompact];
        } else if (rowW >= 320) {
          footerParts = [scopeLabel, inCompact, outCompact, cacheCompact, tpsStr, taskQuotaCompact];
        } else if (rowW >= 245) {
          footerParts = [inCompact, outCompact, cacheCompact, tpsStr];
        } else if (rowW >= 205) {
          footerParts = [inCompact, cacheCompact, tpsStr];
        } else if (rowW >= 150) {
          footerParts = [inCompact, hitStr, tpsStr];
        } else {
          footerParts = tpsStr ? [inCompact, tpsStr] : [inCompact, hitStr];
        }
        const text = footerParts.filter(Boolean).join(' · ');

        let badge = row.querySelector?.('.ag-cm-turn-footer') || null;
        if (!badge) {
          badge = document.createElement('span');
          badge.className = 'ag-cm-turn-footer';
          badge.setAttribute('data-ag-turn-footer', '1');
          badge.setAttribute('role', 'button');
          badge.tabIndex = 0;
          row.prepend ? row.prepend(badge) : row.appendChild?.(badge);
        }
        badge.__turnObj = turnObj;
        badge.__forceFallback = forceFallbackScope;
        badge.__paneSessionId = paneSessionId;
        badge.__paneLatest = paneLatest;
        badge.__scopedTurnKey = scopedTurnKey;
        badge.__tb = tb;
        if (!badge.__agClickBound) {
          badge.__agClickBound = true;
          badge.addEventListener('click', (ev) => {
            ev.stopPropagation?.();
            const curObj = badge.__turnObj;
            if (!curObj || !Array.isArray(curObj.calls)) return;
            if (curObj.calls.length > 1) {
              const curScope = badge.getAttribute('data-scope') || 'turn';
              const nextScope = curScope === 'turn' ? 'request' : 'turn';
              const k = String(badge.__scopedTurnKey || curObj.turnKey || '');
              if (k) turnFooterScopeState.set(k, nextScope);
              applyFooterToToolbar(badge.__tb || tb, curObj, badge.__forceFallback, badge.__paneSessionId, badge.__paneLatest);
            } else {
              if (typeof openDashboardInRightPanel === 'function') void openDashboardInRightPanel();
            }
          });
          badge.addEventListener('dblclick', (ev) => {
            ev.stopPropagation?.();
            if (typeof openDashboardInRightPanel === 'function') void openDashboardInRightPanel();
          });
          badge.addEventListener('keydown', (ev) => {
            if (ev.key === 'Enter' || ev.key === ' ') {
              ev.preventDefault?.();
              ev.stopPropagation?.();
              badge.click();
            }
          });
        }
        // 脏检查幂等写入：数值不变时不重复改写 textContent 与 aria-label，避免唤醒 MutationObserver
        if (badge.textContent !== text) badge.textContent = text;
        const nextScope = isTurnAggregate ? 'turn' : 'request';
        if (badge.getAttribute('data-scope') !== nextScope) badge.setAttribute('data-scope', nextScope);
        if (badge.getAttribute('data-turn-key') !== turnKey) badge.setAttribute('data-turn-key', turnKey);
        if (sidKey && badge.getAttribute('data-ag-pane-session-id') !== sidKey) {
          badge.setAttribute('data-ag-pane-session-id', sidKey);
        }
        tb.__agBoundTurnKey = turnKey;
        tb.__agBoundSessionId = sidKey;
        const nextCallId = String(lastCall.callId || '');
        if (badge.getAttribute('data-call-id') !== nextCallId) badge.setAttribute('data-call-id', nextCallId);
        if (badge.getAttribute('data-multi-call') !== (isMultiCall ? 'true' : 'false')) {
          badge.setAttribute('data-multi-call', isMultiCall ? 'true' : 'false');
        }

        const tp = lastCall.timestamp ? formatReqTimeParts(lastCall) : null;
        const reqTimeStr = tp?.tooltip || tp?.text || (lastCall.date || '—');
        const safeCallId = desensitizeTurnCallId(lastCall.callId);
        const tipAction = isMultiCall ? t('turnFooter.tipMulti') : t('turnFooter.tipSingle');
        const speedMetricTag = actualSpeedKind === 'e2e' ? t('ns.speedMode.e2e') : t('ns.speedMode.streaming');
        const modelDetailStr = modelInfo.models.length > 1
          ? `多模型 · ${modelInfo.models.join(' / ')}${modelInfo.lastCallModel ? ` · 末次请求 ${modelInfo.lastCallModel}` : ''}`
          : `${mName || '未知模型'}${modelInfo.unknownReason ? ` · ${modelInfo.unknownReason}` : ''}`;
        const titleLines = [
          `${scopeLabel}${isTurnAggregate ? ` · ${turnCalls.length} 次请求` : ''} · 模型: ${modelDetailStr}`,
          `${isTurnAggregate ? '末次请求 ID' : '请求 ID'}: ${safeCallId} · 时间: ${reqTimeStr}`,
          `未缓存输入: ${cs.uncachedInput.toLocaleString()} · 缓存读取: ${cs.cacheRead.toLocaleString()} · 总输入: ${cs.totalInput.toLocaleString()} · 命中 ${hitStr}`,
          `输出: ${cs.output.toLocaleString()}${tpsStr ? ` · ${isTurnAggregate ? '末次请求速度' : '速度'}: ${tpsStr} · ${speedMetricTag}` : ''}`,
          tipAction
        ];
        const nextTitle = titleLines.join('\n');
        if (badge.title !== nextTitle) badge.title = nextTitle;
        const nextAria = `${text}。${titleLines.slice(1).join('；')}`;
        if (badge.getAttribute('aria-label') !== nextAria) badge.setAttribute('aria-label', nextAria);
      };

      const alignToolbarsWithTurns = (tbList, turnsList, paneSessionId = undefined, paneLatest = undefined, turnsSource = 'timeline', paneCalls = null) => {
        const M = tbList.length;
        if (M === 0) return;
        const normalToolbars = [];
        for (let i = 0; i < M; i++) {
          const tb = tbList[i];
          if (typeof detectCompactionDomAnchorForToolbar === 'function' && detectCompactionDomAnchorForToolbar(tb)) {
            applyFooterToToolbar(tb, null, false, paneSessionId, paneLatest);
          } else {
            normalToolbars.push(tb);
          }
        }
        const NM = normalToolbars.length;
        if (NM === 0) return;
        const turnCallIds = new Set();
        for (const tr of (turnsList || [])) {
          for (const c of (tr?.calls || [])) {
            if (c?.callId) turnCallIds.add(String(c.callId));
          }
        }
        const callsArr = Array.isArray(paneCalls) ? paneCalls : rawCalls;
        const hasUnmappedLaterCalls = callsArr.some(c => c && c.agentRole !== 'subagent' && c.callId && !turnCallIds.has(String(c.callId)));
        const toolbarMetas = normalToolbars.map((tb) => {
          const existingBadge = tb?.querySelector?.('.ag-cm-turn-footer') || null;
          return {
            existingTurnKey: String(existingBadge?.getAttribute?.('data-turn-key') || tb?.__agBoundTurnKey || '').trim(),
            existingSessionId: String(existingBadge?.getAttribute?.('data-ag-pane-session-id') || tb?.__agBoundSessionId || '').trim()
          };
        });
        const coreApi = typeof window !== 'undefined' ? window.__AGContextMeterCore : null;
        const matchedTurns = typeof coreApi?.alignTurnFootersWithTurns === 'function'
          ? coreApi.alignTurnFootersWithTurns(toolbarMetas, turnsList, {
              sessionId: paneSessionId || state.route || '',
              turnsSource,
              hasUnmappedLaterCalls
            })
          : (() => {
            const T = turnsList.length;
            const out = new Array(NM).fill(null);
            if (T === 0) return out;
            if (NM <= T) {
              const offset = T - NM;
              for (let i = 0; i < NM; i++) out[i] = turnsList[offset + i] || null;
            } else {
              for (let i = 0; i < T; i++) out[i] = turnsList[i] || null;
            }
            return out;
          })();
        for (let i = 0; i < NM; i++) {
          applyFooterToToolbar(normalToolbars[i], matchedTurns[i] || null, false, paneSessionId, paneLatest);
        }
      };

      if (isMultiPaneView) {
        const assignedToolbars = new Set();
        for (const pane of visiblePanes) {
          const pData = resolveSessionDataForPane(pane.sessionId, pane.isFocused);
          const pTurnsInfo = buildAuthoritativeMainTurns(pane.sessionId, pData.sessionTimeline, pData.sessionCalls);
          const timelineCooldownOk = !state.lastTimelineFetchAt || (Date.now() - state.lastTimelineFetchAt) >= 2500;
          if (pane.isFocused && pane.toolbars.length > pTurnsInfo.turns.length && timelineCooldownOk && state.route && !state.timelineLoading && !state.timelineError && typeof fetchSessionTimeline === 'function') {
            void fetchSessionTimeline(state.route, { force: true });
          }
          if (!pData.hydrated && pane.sessionId) {
            syncBackgroundSplitPaneSessions();
          }
          alignToolbarsWithTurns(pane.toolbars, pTurnsInfo.turns, pane.sessionId, pData.latest, pTurnsInfo.source, pData.sessionCalls);
          for (const tb of pane.toolbars) assignedToolbars.add(tb);
        }
        // 未归属于任何已识别窗格的残余工具栏清理旧尾标，杜绝错挂
        for (const tb of mainToolbars) {
          if (!assignedToolbars.has(tb)) applyFooterToToolbar(tb, null);
        }
      } else {
        const { source, turns } = buildAuthoritativeMainTurns();
        const timelineCooldownOk = !state.lastTimelineFetchAt || (Date.now() - state.lastTimelineFetchAt) >= 2500;
        if (mainToolbars.length > turns.length && timelineCooldownOk && state.route && !state.timelineLoading && !state.timelineError && typeof fetchSessionTimeline === 'function') {
          void fetchSessionTimeline(state.route, { force: true });
        }
        alignToolbarsWithTurns(mainToolbars, turns, state.route, state.latest, source, rawCalls);
      }

      if (sideToolbars.length > 0) {
        const latestCall = rawCalls[rawCalls.length - 1] || null;
        for (let s = 0; s < sideToolbars.length; s++) {
          if (s === sideToolbars.length - 1 && latestCall) {
            applyFooterToToolbar(sideToolbars[s], {
              turnKey: `side-${latestCall.callId || 'latest'}`,
              calls: [latestCall]
            }, true);
          } else {
            applyFooterToToolbar(sideToolbars[s], null);
          }
        }
      }
    } catch { }
  }


  function switchTokenView(v) {
    activeTokenView = v;
    // 离开 Token 统计视图时关闭订阅详情与表单
    setPlanDetailExpanded(false, { skipReposition: true });
    if (typeof hidePopover === 'function') hidePopover();

    setPillActive(el('tok-view-tokens'), v === 'tokens');
    setPillActive(el('tok-view-models'), v === 'models');
    setPillActive(el('tok-view-cost'), v === 'cost');
    setPillActive(el('tok-view-requests'), v === 'requests');
    const costCard = el('cost-estimate-card');
    const modelView = el('model-usage-view');
    const reqView = el('requests-live-view');
    const tokensMain = el('tokens-main-view');
    const statCards = el('token-stat-cards');
    const planBar = el('plan-summary-bar');
    const titleTokens = el('panel-tokens-title');
    const pTokens = el('panel-tokens');

    if (costCard) {
      costCard.style.display = v === 'cost' ? 'block' : 'none';
      if (v === 'cost') costCard.style.animation = 'agFadeIn .18s cubic-bezier(0.16,1,0.3,1)';
    }
    if (modelView) {
      modelView.style.display = v === 'models' ? 'block' : 'none';
      if (v === 'models') {
        modelView.style.animation = 'agFadeIn .18s cubic-bezier(0.16,1,0.3,1)';
        renderModelUsageView();
      }
    }
    if (reqView) {
      reqView.style.display = v === 'requests' ? 'flex' : 'none';
      if (v === 'requests') {
        reqView.style.animation = 'agFadeIn .18s cubic-bezier(0.16,1,0.3,1)';
        renderRequestsLiveView({ force: true });
        if (!lastHistorySync || (Date.now() - lastHistorySync) > 5000) {
          lastRequestsLiveSyncAt = Date.now();
          void syncTokenHistoryFromHost(false);
        }
      }
    }
    if (tokensMain) {
      tokensMain.style.display = v === 'tokens' ? 'block' : 'none';
      if (v === 'tokens') {
        tokensMain.style.animation = 'agFadeIn .18s cubic-bezier(0.16,1,0.3,1)';
        renderActiveHeatView();
      }
    }
    if (statCards) statCards.style.display = v === 'tokens' ? 'grid' : 'none';
    if (planBar) planBar.style.display = v === 'tokens' ? 'flex' : 'none';
    if (titleTokens) {
      titleTokens.textContent = v === 'cost'
        ? t('tokens.titleCost')
        : v === 'models'
          ? t('tokens.titleModels')
          : v === 'requests'
            ? t('tokens.titleRequests')
            : t('tokens.title');
    }

    if (pTokens) {
      const isCompact = v === 'cost' && !costDetailsExpanded;
      const isWideRequests = v === 'requests';
      pTokens.classList?.toggle?.('cost-compact-view', isCompact);
      pTokens.classList?.toggle?.('requests-wide-view', isWideRequests);
      let curCls = pTokens.getAttribute?.('class') || '';
      if (isCompact) {
        if (!curCls.includes('cost-compact-view')) curCls = (curCls + ' cost-compact-view').trim();
      } else {
        curCls = curCls.replace(/\bcost-compact-view\b/g, '').trim();
      }
      if (isWideRequests) {
        if (!curCls.includes('requests-wide-view')) curCls = (curCls + ' requests-wide-view').trim();
      } else {
        curCls = curCls.replace(/\brequests-wide-view\b/g, '').trim();
      }
      pTokens.setAttribute?.('class', curCls);
    }
    positionFloatingPanels();
    syncPanelPickerActiveState();
    if (state.orbLinkedPanel && typeof syncFloatingOrbState === 'function') syncFloatingOrbState();
  }
  el('tok-view-tokens')?.addEventListener('click', () => switchTokenView('tokens'));
  el('tok-view-models')?.addEventListener('click', () => switchTokenView('models'));
  el('tok-view-cost')?.addEventListener('click', () => switchTokenView('cost'));
  el('tok-view-requests')?.addEventListener('click', () => switchTokenView('requests'));
  el('req-filter-all')?.addEventListener('click', () => { reqLogStatusFilter = 'all'; reqLogPageLimit = 50; renderRequestsLiveView({ force: true }); });
  el('req-filter-success')?.addEventListener('click', () => { reqLogStatusFilter = 'success'; reqLogPageLimit = 50; renderRequestsLiveView({ force: true }); });
  el('req-filter-error')?.addEventListener('click', () => { reqLogStatusFilter = 'error'; reqLogPageLimit = 50; renderRequestsLiveView({ force: true }); });
  el('req-sort-bar')?.addEventListener('click', (e) => {
    const btn = e?.target?.closest?.('[data-req-sort]') || (e?.target?.getAttribute?.('data-req-sort') ? e.target : null);
    const sortVal = btn?.getAttribute?.('data-req-sort');
    if (sortVal && ['time_desc', 'tokens_desc', 'cost_desc', 'duration_desc', 'speed_desc'].includes(sortVal)) {
      reqLogSortBy = sortVal;
      reqLogPageLimit = 50;
      renderRequestsLiveView({ force: true });
    }
  });
  el('btn-req-live-more')?.addEventListener('click', () => { reqLogPageLimit = (Number(reqLogPageLimit) || 50) + 50; renderRequestsLiveView({ force: true }); });
  let pricingSyncBusy = false;
  let pricingSyncNoteState = null;
  let pricingSyncNoteTimer = null;
  earlyDisposeHooks.push(() => {
    if (pricingSyncNoteTimer) {
      clearTimeout(pricingSyncNoteTimer);
      pricingSyncNoteTimer = null;
    }
  });

  function formatPricingSyncShortTime(isoStr) {
    if (!isoStr) return '';
    const ts = Date.parse(isoStr);
    if (!Number.isFinite(ts)) return '';
    const d = new Date(ts);
    const pad2 = n => String(n).padStart(2, '0');
    return `${pad2(d.getMonth() + 1)}-${pad2(d.getDate())} ${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
  }

  function updatePricingSyncButtonTooltip(cat = null) {
    const info = cat || (typeof getDynamicPricingCatalog === 'function' ? getDynamicPricingCatalog() : null);
    const hasSynced = Boolean(info && Number(info.modelCount) > 0 && info.updatedAt);
    const tip = hasSynced
      ? t('reqLog.syncPricingTitleUpdated', {
        count: Number(info.modelCount) || 0,
        sources: Array.isArray(info.sources) && info.sources.length ? info.sources.join(' + ') : 'models.dev',
        time: formatPricingSyncShortTime(info.updatedAt)
      })
      : t('reqLog.syncPricingTitle');
    for (const id of ['btn-req-sync-pricing', 'btn-cost-sync-pricing']) {
      const btn = el(id);
      if (btn) btn.title = tip;
    }
  }

  function renderPricingSyncUiState() {
    for (const id of ['btn-req-sync-pricing', 'btn-cost-sync-pricing']) {
      const btn = el(id);
      if (!btn) continue;
      btn.disabled = pricingSyncBusy;
      btn.textContent = pricingSyncBusy ? t('reqLog.syncingPricing') : t('reqLog.syncPricing');
    }
    for (const id of ['req-pricing-sync-note', 'cost-pricing-sync-note']) {
      const noteEl = el(id);
      if (!noteEl) continue;
      const baseCls = id === 'req-pricing-sync-note' ? 'req-pricing-sync-note' : 'cost-pricing-sync-note';
      if (!pricingSyncNoteState || !pricingSyncNoteState.text) {
        noteEl.style.display = 'none';
        noteEl.textContent = '';
        noteEl.className = baseCls;
      } else {
        noteEl.style.display = id === 'req-pricing-sync-note' ? 'inline-flex' : 'block';
        noteEl.textContent = pricingSyncNoteState.text;
        const toneCls = pricingSyncNoteState.kind === 'err' ? ' is-err' : (pricingSyncNoteState.kind === 'ok' ? ' is-ok' : '');
        noteEl.className = `${baseCls}${toneCls}`;
      }
    }
    updatePricingSyncButtonTooltip();
  }

  async function triggerSyncPricingCatalog(opts = {}) {
    if (pricingSyncBusy) return { ok: false, busy: true };
    pricingSyncBusy = true;
    if (pricingSyncNoteTimer) {
      clearTimeout(pricingSyncNoteTimer);
      pricingSyncNoteTimer = null;
    }
    pricingSyncNoteState = { kind: 'busy', text: t('reqLog.syncingPricing') };
    renderPricingSyncUiState();
    try {
      const out = await callBackendWithPriority({
        ipcCall: typeof window?.contextMeterAPI?.syncPricing === 'function'
          ? () => window.contextMeterAPI.syncPricing({ force: opts.force !== false })
          : null,
        liveRoute: '/sync-pricing',
        liveBody: { force: opts.force !== false },
        liveFetchOpts: { timeoutMs: 20000 }
      });
      const res = out?.result || null;
      if (res && res.ok) {
        const count = Number(res.modelCount) || 0;
        const repriced = Number(res.repricedCount) || 0;
        pricingSyncNoteState = {
          kind: 'ok',
          text: repriced > 0
            ? t('reqLog.syncPricingDoneRepriced', { count, repriced })
            : t('reqLog.syncPricingDone', { count })
        };
        await syncTokenHistoryFromHost(true);
        renderRequestsLiveView({ force: true });
        pricingSyncNoteTimer = setTimeout(() => {
          pricingSyncNoteState = null;
          renderPricingSyncUiState();
        }, 8000);
        return res;
      }
      const errMsg = res?.error || 'network_error';
      pricingSyncNoteState = { kind: 'err', text: t('reqLog.syncPricingFailed', { error: errMsg }) };
      return { ok: false, error: errMsg };
    } catch (err) {
      const errMsg = err?.message || String(err || 'network_error');
      pricingSyncNoteState = { kind: 'err', text: t('reqLog.syncPricingFailed', { error: errMsg }) };
      return { ok: false, error: errMsg };
    } finally {
      pricingSyncBusy = false;
      renderPricingSyncUiState();
    }
  }

  el('btn-req-sync-pricing')?.addEventListener('click', () => {
    void triggerSyncPricingCatalog({ force: true });
  });
  el('btn-cost-sync-pricing')?.addEventListener('click', () => {
    void triggerSyncPricingCatalog({ force: true });
  });
  el('btn-req-live-refresh')?.addEventListener('click', () => {
    lastRequestsLiveSyncAt = Date.now();
    renderRequestsLiveView({ force: true });
    void syncTokenHistoryFromHost(true);
  });


